pub type QueryResult<T> = core::result::Result<T, QueryError>;
fn parse_canonical_i105_account_id(value: &str, field: &str) -> Result<AccountId> {
    let trimmed = value.trim();
    if trimmed != value {
        return Err(eyre!("{field} must not contain surrounding whitespace"));
    }
    let parsed = AccountId::parse_encoded(trimmed)
        .map_err(|err| eyre!("{field} must be a canonical I105 account id: {err}"))?;
    if parsed.to_string() != value {
        return Err(eyre!(
            "{field} must use the canonical domainless I105 representation"
        ));
    }
    Ok(parsed)
}
fn ensure_canonical_i105_account_id(value: &str, field: &str) -> Result<()> {
    parse_canonical_i105_account_id(value, field).map(drop)
}
fn ensure_typed_account_id_is_canonical(account_id: &AccountId, field: &str) -> Result<()> {
    let canonical = account_id.to_string();
    let reparsed = parse_canonical_i105_account_id(&canonical, field)?;
    if &reparsed != account_id {
        return Err(eyre!("{field} must be a canonical domainless account id"));
    }
    Ok(())
}
fn parse_canonical_account_alias(value: &str, field: &str) -> Result<AccountAliasName> {
    let alias = value
        .parse::<AccountAliasName>()
        .map_err(|error| eyre!("invalid {field}: {error}"))?;
    if alias.to_string() != value {
        return Err(eyre!(
            "{field} must use its canonical textual representation"
        ));
    }
    Ok(alias)
}
fn ensure_typed_account_alias_is_canonical(alias: &AccountAliasName, field: &str) -> Result<()> {
    if !alias.is_canonical() {
        return Err(eyre!("{field} must be a canonical account alias"));
    }
    let canonical = alias.to_string();
    let reparsed = parse_canonical_account_alias(&canonical, field)?;
    if reparsed != *alias {
        return Err(eyre!("{field} must be a canonical account alias"));
    }
    Ok(())
}
fn canonical_alias_read_source(source: Option<String>, field: &str) -> Result<Option<String>> {
    let Some(source) = source else {
        return Ok(None);
    };
    let bytes = source.as_bytes();
    if bytes.is_empty()
        || bytes.len() > 64
        || !bytes[0].is_ascii_lowercase()
        || !bytes
            .iter()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || *byte == b'_')
    {
        return Err(eyre!(
            "{field} must be a canonical lowercase ASCII identifier"
        ));
    }
    Ok(Some(source))
}
fn alias_text_cmp(left: &AccountAliasName, right: &AccountAliasName) -> std::cmp::Ordering {
    left.to_string().cmp(&right.to_string())
}
fn decode_account_alias_absence(
    response: &Response<Vec<u8>>,
    expected_code: &str,
) -> Result<iroha_torii_shared::ErrorEnvelope> {
    let mut content_types = response.headers().get_all("Content-Type").iter();
    let content_type = content_types
        .next()
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next());
    eyre::ensure!(
        content_types.next().is_none()
            && content_type
                .is_some_and(|value| value.trim().eq_ignore_ascii_case(APPLICATION_JSON)),
        "account-alias absence requires one application/json Content-Type header"
    );
    eyre::ensure!(
        response.status() == StatusCode::NOT_FOUND
            && response.body().len()
                <= iroha_torii_shared::aliases::ACCOUNT_ALIAS_ABSENCE_MAX_BYTES,
        "account-alias absence requires bounded HTTP 404"
    );
    let envelope: iroha_torii_shared::ErrorEnvelope = norito::json::from_slice(response.body())
        .wrap_err("decode account-alias absence ErrorEnvelope")?;
    eyre::ensure!(
        envelope.code() == expected_code,
        "account-alias lookup returned HTTP 404 code `{}` instead of exact ledger absence",
        envelope.code()
    );
    Ok(envelope)
}
fn decode_account_alias_resolution(
    response: &Response<Vec<u8>>,
    expected_alias: &AccountAliasName,
) -> Result<Option<AccountAliasResolutionV1>> {
    match response.status() {
        StatusCode::NOT_FOUND => {
            let envelope = decode_account_alias_absence(
                response,
                iroha_torii_shared::aliases::ACCOUNT_ALIAS_NOT_FOUND_CODE,
            )?;
            let absence = envelope
                .details
                .as_ref()
                .and_then(|details| details.account_alias_not_found.as_ref())
                .ok_or_else(|| eyre!("account-alias absence omitted its typed selector"))?;
            eyre::ensure!(
                absence.alias == expected_alias.to_string(),
                "account-alias absence selector differs from the requested alias"
            );
            Ok(None)
        }
        StatusCode::OK => {
            let wire: AccountAliasResolutionWireV1 = norito::json::from_slice(response.body())
                .wrap_err("decode account-alias resolution response")?;
            let alias = parse_canonical_account_alias(&wire.alias, "response.alias")?;
            if &alias != expected_alias {
                return Err(eyre!(
                    "account-alias response selector differs from the requested alias"
                ));
            }
            let account_id =
                parse_canonical_i105_account_id(&wire.account_id, "response.account_id")?;
            AccountAliasResolutionV1::try_new(
                alias,
                account_id,
                wire.index.map(AliasIndex),
                wire.source,
            )
            .map(Some)
        }
        status => Err(eyre!(
            "account-alias resolution failed with HTTP status {status}"
        )),
    }
}
fn decode_account_alias_index_resolution(
    response: &Response<Vec<u8>>,
    expected_index: AliasIndex,
) -> Result<Option<AccountAliasIndexResolutionV1>> {
    match response.status() {
        StatusCode::NOT_FOUND => Ok(None),
        StatusCode::OK => {
            let wire: AccountAliasIndexResolutionWireV1 = norito::json::from_slice(response.body())
                .wrap_err("decode account-alias index resolution response")?;
            if wire.index != expected_index.0 {
                return Err(eyre!(
                    "account-alias index response selector differs from the requested index"
                ));
            }
            let alias = parse_canonical_account_alias(&wire.alias, "response.alias")?;
            let account_id =
                parse_canonical_i105_account_id(&wire.account_id, "response.account_id")?;
            AccountAliasIndexResolutionV1::try_new(
                AliasIndex(wire.index),
                alias,
                account_id,
                wire.source,
            )
            .map(Some)
        }
        status => Err(eyre!(
            "account-alias index resolution failed with HTTP status {status}"
        )),
    }
}
fn decode_account_aliases_by_account(
    response: &Response<Vec<u8>>,
    request: &AccountAliasesByAccountRequestV1,
) -> Result<Option<AccountAliasesByAccountV1>> {
    match response.status() {
        StatusCode::NOT_FOUND => {
            let envelope = decode_account_alias_absence(
                response,
                iroha_torii_shared::aliases::ACCOUNT_ALIASES_BY_ACCOUNT_NOT_FOUND_CODE,
            )?;
            let absence = envelope
                .details
                .as_ref()
                .and_then(|details| details.account_aliases_by_account_not_found.as_ref())
                .ok_or_else(|| {
                    eyre!("account aliases-by-account absence omitted its typed selector")
                })?;
            eyre::ensure!(
                absence.matches_selector(
                    &request.account_id().to_string(),
                    request.dataspace().map(AsRef::as_ref),
                    request.domain().map(AsRef::as_ref)
                ),
                "account aliases-by-account absence differs from the requested account or scope"
            );
            Ok(None)
        }
        StatusCode::OK => {
            let wire: AccountAliasesByAccountWireV1 = norito::json::from_slice(response.body())
                .wrap_err("decode account aliases-by-account response")?;
            if wire.account_id != request.account_id().to_string() {
                return Err(eyre!(
                    "account aliases-by-account response selector differs from the requested account"
                ));
            }
            let account_id =
                parse_canonical_i105_account_id(&wire.account_id, "response.account_id")?;
            if &account_id != request.account_id() {
                return Err(eyre!(
                    "account aliases-by-account response selector differs from the requested account"
                ));
            }
            if wire.total != u64::try_from(wire.items.len()).unwrap_or(u64::MAX) {
                return Err(eyre!(
                    "account aliases-by-account response total differs from its item count"
                ));
            }
            let mut previous_alias: Option<String> = None;
            let mut items = Vec::with_capacity(wire.items.len());
            for (index, item) in wire.items.into_iter().enumerate() {
                if previous_alias
                    .as_ref()
                    .is_some_and(|previous| previous >= &item.alias)
                {
                    return Err(eyre!(
                        "account aliases-by-account response items are not in strict canonical alias order at index {index}"
                    ));
                }
                previous_alias = Some(item.alias.clone());
                let alias = parse_canonical_account_alias(
                    &item.alias,
                    &format!("response.items[{index}].alias"),
                )?;
                if item.dataspace != alias.dataspace.as_ref()
                    || item.domain.as_deref() != alias.domain.as_ref().map(AsRef::as_ref)
                {
                    return Err(eyre!(
                        "account aliases-by-account response item {index} has scope fields that differ from its alias"
                    ));
                }
                if request
                    .dataspace()
                    .is_some_and(|expected| expected != &alias.dataspace)
                    || request
                        .domain()
                        .is_some_and(|expected| alias.domain.as_ref() != Some(expected))
                {
                    return Err(eyre!(
                        "account aliases-by-account response item {index} falls outside the requested scope"
                    ));
                }
                items.push(AccountAliasListItemV1::try_new(alias, item.is_primary)?);
            }
            let source = canonical_alias_read_source(wire.source, "response.source")?;
            Ok(Some(AccountAliasesByAccountV1 {
                account_id,
                items,
                source,
            }))
        }
        status => Err(eyre!(
            "account aliases-by-account lookup failed with HTTP status {status}"
        )),
    }
}
const FAUCET_CLAIM_HASH_DOMAIN_V1: &[u8] = b"iroha:accounts:faucet:claim:v1\0";
const PREPARED_BINDING_METADATA_KEY_V1: &str = "prepared_operation_binding";
const PREPARED_OPERATION_METADATA_KEY_V1: &str = "prepared_operation";
const PREPARED_SEMANTIC_HASH_METADATA_KEY_V1: &str = "prepared_semantic_hash";

fn lower_hex_with_len(value: &str, length: usize) -> bool {
    value.len() == length
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn validate_prepared_mutation_binding(
    binding: &PreparedOperationBindingV1,
    expected_kind: &str,
    require_active: bool,
) -> Result<()> {
    let now_ms: u64 = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .try_into()
        .unwrap_or(u64::MAX);
    if binding.schema != PreparedOperationBindingV1::SCHEMA
        || binding.kind != expected_kind
        || !lower_hex_with_len(&binding.semantic_hash_hex, 64)
        || !lower_hex_with_len(&binding.request_id, 64)
        || binding.execution_expires_at_unix_ms == 0
        || (require_active && binding.execution_expires_at_unix_ms <= now_ms)
    {
        return Err(eyre!(
            "prepared transaction binding is noncanonical, expired, or belongs to another operation"
        ));
    }
    Ok(())
}

fn validate_public_prepared_transaction_lifetime(
    transaction: &SignedTransaction,
    binding: &PreparedOperationBindingV1,
) -> Result<()> {
    let creation = u64::try_from(transaction.creation_time().as_millis())
        .map_err(|_| eyre!("prepared transaction creation time overflows"))?;
    let ttl = transaction
        .time_to_live()
        .and_then(|ttl| u64::try_from(ttl.as_millis()).ok())
        .filter(|ttl| *ttl > 0)
        .ok_or_else(|| eyre!("prepared transaction requires a positive bounded TTL"))?;
    if creation
        .checked_add(ttl)
        .is_none_or(|expiry| expiry > binding.execution_expires_at_unix_ms)
    {
        return Err(eyre!(
            "prepared transaction outlives its operation deadline"
        ));
    }
    Ok(())
}

fn validate_prepared_semantic_binding(
    binding: &PreparedOperationBindingV1,
    semantic_hash_hex: &str,
    semantic_expires_at_unix_ms: u64,
) -> Result<()> {
    if binding.semantic_hash_hex != semantic_hash_hex
        || binding.execution_expires_at_unix_ms == 0
        || binding.execution_expires_at_unix_ms > semantic_expires_at_unix_ms
    {
        return Err(eyre!(
            "prepared operation binding differs from its exact semantic intent or deadline"
        ));
    }
    Ok(())
}

trait PreparedSignatureTranscriptV1 {
    fn signature_transcript(&self) -> Result<Vec<u8>>;
}

fn verify_prepared_payload_signature(
    payload: &impl PreparedSignatureTranscriptV1,
    signature: &Signature,
    authority: &AccountId,
) -> Result<()> {
    let key = authority
        .try_signatory()
        .ok_or_else(|| eyre!("prepared transaction authority is not a single-signatory account"))?;
    let transcript = payload.signature_transcript()?;
    let hash = iroha_torii_shared::prepared_transaction::prepared_signature_digest_v1(&transcript);
    signature
        .verify(key, hash.as_ref())
        .wrap_err("prepared transaction envelope signature is invalid")
}

fn decode_canonical_prepared_transaction(
    transaction_hash_hex: &str,
    wire_hex: &str,
    wire_sha256: &str,
) -> Result<SignedTransaction> {
    if !lower_hex_with_len(transaction_hash_hex, 64)
        || !lower_hex_with_len(wire_sha256, 64)
        || wire_hex.is_empty()
        || !wire_hex.len().is_multiple_of(2)
        || !wire_hex
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(eyre!(
            "prepared transaction hashes or wire hexadecimal are noncanonical"
        ));
    }
    let wire = hex::decode(wire_hex).wrap_err("decode prepared transaction wire hexadecimal")?;
    if hex::encode(Sha256::digest(&wire)) != wire_sha256 {
        return Err(eyre!(
            "prepared transaction wire SHA-256 does not match the envelope"
        ));
    }
    let transaction = SignedTransaction::decode_all_versioned(&wire)
        .wrap_err("decode fixed-V1 prepared SignedTransaction wire")?;
    let canonical = transaction
        .encode_wire_v1()
        .wrap_err("re-encode canonical prepared SignedTransaction wire")?;
    if canonical != wire
        || hex::encode(transaction.hash().as_ref()) != transaction_hash_hex
        || hex::encode(Sha256::digest(&canonical)) != wire_sha256
    {
        return Err(eyre!(
            "prepared transaction wire, hash, or canonical re-encoding changed identity"
        ));
    }
    transaction
        .verify_signature()
        .wrap_err("prepared transaction signature is invalid")?;
    Ok(transaction)
}

fn faucet_claim_hash(claim: &AccountFaucetClaimV1) -> Hash {
    let encoded = claim.encode();
    Hash::new_from_chunks(&[FAUCET_CLAIM_HASH_DOMAIN_V1, encoded.as_slice()])
}

fn expected_prepared_transaction_metadata(
    binding: &PreparedOperationBindingV1,
    operation: &str,
    semantic_hash_hex: &str,
) -> Result<Metadata> {
    let binding_value = norito::json::to_value(binding)
        .wrap_err("encode prepared transaction binding as Norito JSON")?;
    let binding_json = iroha_primitives::json::Json::from_norito_value_ref(&binding_value)
        .wrap_err("canonicalize prepared transaction binding metadata")?;
    let mut metadata = Metadata::default();
    metadata.insert(
        PREPARED_BINDING_METADATA_KEY_V1
            .parse()
            .expect("static binding metadata key"),
        binding_json,
    );
    metadata.insert(
        PREPARED_OPERATION_METADATA_KEY_V1
            .parse()
            .expect("static operation metadata key"),
        iroha_primitives::json::Json::new(operation.to_owned()),
    );
    metadata.insert(
        PREPARED_SEMANTIC_HASH_METADATA_KEY_V1
            .parse()
            .expect("static semantic-hash metadata key"),
        iroha_primitives::json::Json::new(semantic_hash_hex.to_owned()),
    );
    if operation == iroha_data_model::transaction::PREPARED_FAUCET_OPERATION {
        metadata.insert(
            iroha_data_model::transaction::FAUCET_CLAIM_MARKER_VERSION_METADATA_KEY
                .parse()
                .expect("static faucet claim marker version metadata key"),
            iroha_primitives::json::Json::new(
                iroha_data_model::transaction::FAUCET_CLAIM_MARKER_VERSION_V1,
            ),
        );
    }
    Ok(metadata)
}

fn onboarding_disposition_transition_allowed(
    planned: AliasPlanDispositionV1,
    prepared: AliasPlanDispositionV1,
) -> bool {
    use AliasPlanDispositionV1::{Create, NoOp, Repair};
    matches!(
        (planned, prepared),
        (Create, Create | Repair | NoOp) | (Repair, Repair | NoOp) | (NoOp, NoOp)
    )
}

fn instructions_are_ordered_subset(actual: &[InstructionBox], planned: &[InstructionBox]) -> bool {
    let mut actual = actual.iter();
    let mut next = actual.next();
    for instruction in planned {
        if next.is_some_and(|candidate| candidate == instruction) {
            next = actual.next();
        }
    }
    next.is_none()
}

fn validate_account_faucet_claim(claim: &AccountFaucetClaimV1) -> Result<AccountId> {
    ensure_canonical_i105_account_id(&claim.account_id, "claim.account_id")?;
    let account_id = AccountId::parse_encoded(&claim.account_id)
        .map_err(|error| eyre!("invalid faucet claim account_id: {error}"))?;
    if account_id.to_string() != claim.account_id {
        return Err(eyre!(
            "faucet claim account_id must use its canonical domainless representation"
        ));
    }
    if claim.pow_anchor_height == 0 {
        return Err(eyre!(
            "faucet proof anchor height must be a positive committed height"
        ));
    }
    let nonce = claim.pow_nonce_hex.as_str();
    if nonce.is_empty()
        || nonce.len() > 64
        || !nonce.len().is_multiple_of(2)
        || !nonce
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(eyre!(
            "faucet proof nonce must use 1..32 bytes of canonical lowercase hexadecimal"
        ));
    }
    Ok(account_id)
}

fn validate_faucet_transaction_identity(
    prepared: &AccountFaucetPreparedTransactionV1,
    transaction: &SignedTransaction,
    policy: &AccountFaucetPolicyV1,
) -> Result<()> {
    let account_id = validate_account_faucet_claim(&prepared.claim)?;
    let asset_definition_id: AssetDefinitionId = prepared
        .asset_definition_id
        .parse()
        .wrap_err("parse prepared faucet asset definition")?;
    if asset_definition_id.to_string() != prepared.asset_definition_id
        || &asset_definition_id != policy.asset_definition_id()
        || &prepared.amount != policy.amount()
    {
        return Err(eyre!(
            "prepared faucet asset definition or amount differs from the trusted policy"
        ));
    }
    if transaction.authority() != policy.faucet_authority() {
        return Err(eyre!(
            "prepared faucet transaction authority differs from the trusted policy"
        ));
    }
    let destination_asset_id =
        AssetId::new(policy.asset_definition_id().clone(), account_id.clone());
    if destination_asset_id.to_string() != prepared.asset_id {
        return Err(eyre!(
            "prepared faucet destination asset differs from the exact claim"
        ));
    }
    let source_asset_id = AssetId::new(
        policy.asset_definition_id().clone(),
        policy.faucet_authority().clone(),
    );
    let transfer: InstructionBox = iroha_data_model::isi::Transfer::asset_quantity(
        source_asset_id,
        policy.amount().clone(),
        account_id.clone(),
    )
    .into();
    let without_registration = vec![transfer.clone()];
    let with_registration = vec![
        InstructionBox::from(iroha_data_model::isi::Register::account(
            iroha_data_model::account::Account::new(account_id),
        )),
        transfer,
    ];
    let Executable::Instructions(instructions) = transaction.instructions() else {
        return Err(eyre!(
            "prepared faucet transaction must contain a direct instruction sequence"
        ));
    };
    if instructions.as_ref() != without_registration.as_slice()
        && instructions.as_ref() != with_registration.as_slice()
    {
        return Err(eyre!(
            "prepared faucet transaction instructions differ from its exact claim"
        ));
    }
    Ok(())
}

/// Authenticate an exact prepared onboarding transaction without constructing a client.
///
/// Expired bindings remain verifiable for durable recovery, but the signed transaction's
/// lifetime must fit within its binding deadline. Submission separately requires an active binding.
///
/// # Errors
/// Returns an error for any substituted request, receipt, binding, wire, signature, network,
/// authority, fee intent, metadata, or instruction sequence.
pub fn verify_account_onboarding_prepared_transaction_v1(
    expected_network_id: NetworkId,
    request: &AccountOnboardingPlanRequestV1,
    prepared: &AccountOnboardingPreparedTransactionV1,
    receipt: &AccountOnboardingPlanReceiptV1,
    binding: &PreparedOperationBindingV1,
    expected_fee_payment: &FeePaymentIntent,
) -> Result<SignedTransaction> {
    validate_prepared_semantic_binding(
        binding,
        &hex::encode(receipt.plan_hash.as_ref()),
        receipt.body.valid_until_ms,
    )?;
    expected_fee_payment
        .validate()
        .map_err(|error| eyre!("invalid requested onboarding fee payment: {error}"))?;
    prepared
        .fee_payment
        .validate()
        .map_err(|error| eyre!("invalid prepared onboarding fee payment: {error}"))?;
    validate_prepared_mutation_binding(
        &prepared.binding,
        AccountOnboardingPreparedTransactionV1::OPERATION,
        false,
    )?;
    if prepared.schema != AccountOnboardingPreparedTransactionV1::SCHEMA
        || prepared.operation != AccountOnboardingPreparedTransactionV1::OPERATION
        || &prepared.binding != binding
        || &prepared.receipt != receipt
        || prepared.semantic_hash_hex != hex::encode(receipt.plan_hash.as_ref())
        || prepared.account_id != receipt.body.request.account_id
        || prepared.alias != receipt.body.request.alias
        || !onboarding_disposition_transition_allowed(
            receipt.body.resource.disposition,
            prepared.disposition,
        )
    {
        return Err(eyre!(
            "prepared onboarding envelope differs from its exact receipt or binding"
        ));
    }
    let planned_instructions = decode_and_verify_account_onboarding_plan_for_request(
        expected_network_id,
        request,
        receipt,
    )?;
    verify_prepared_payload_signature(
        &AccountOnboardingPreparedSignaturePayloadV1::from(prepared),
        &prepared.server_signature,
        &receipt.body.authority,
    )?;
    let transaction = decode_canonical_prepared_transaction(
        &prepared.transaction_hash_hex,
        &prepared.signed_transaction_wire_hex,
        &prepared.signed_transaction_wire_sha256,
    )?;

    validate_public_prepared_transaction_lifetime(&transaction, binding)?;
    let Executable::Instructions(instructions) = transaction.instructions() else {
        return Err(eyre!(
            "prepared onboarding transaction must contain a direct instruction sequence"
        ));
    };
    let expected_metadata = expected_prepared_transaction_metadata(
        binding,
        AccountOnboardingPreparedTransactionV1::OPERATION,
        &prepared.semantic_hash_hex,
    )?;
    if transaction.metadata() != &expected_metadata {
        return Err(eyre!(
            "prepared onboarding transaction metadata differs from its exact binding and operation"
        ));
    }
    if transaction.network_id() != Some(&expected_network_id)
        || transaction.authority() != &receipt.body.authority
        || transaction.payload().fee_payment != prepared.fee_payment
        || !expected_fee_payment.has_same_payer_and_gas_bound(&prepared.fee_payment)
        || instructions.is_empty()
        || !instructions_are_ordered_subset(instructions.as_ref(), &planned_instructions)
    {
        return Err(eyre!(
            "prepared onboarding transaction network, authority, or fee intent was substituted"
        ));
    }
    Ok(transaction)
}

/// Authenticate an exact prepared faucet transaction without constructing a client.
///
/// Requires the canonical V1 faucet claim marker and exact operation metadata. Expired bindings
/// remain verifiable for durable recovery only when the signed lifetime fits within the deadline;
/// submission separately requires an active binding.
///
/// # Errors
/// Returns an error for any substituted claim, binding, wire, signature, network, authority,
/// fee intent, metadata, asset definition, destination, amount, or instruction sequence.
pub fn verify_account_faucet_prepared_transaction_v1(
    expected_network_id: NetworkId,
    prepared: &AccountFaucetPreparedTransactionV1,
    claim: &AccountFaucetClaimV1,
    binding: &PreparedOperationBindingV1,
    expected_fee_payment: &FeePaymentIntent,
    policy: &AccountFaucetPolicyV1,
) -> Result<SignedTransaction> {
    validate_prepared_semantic_binding(
        binding,
        &hex::encode(faucet_claim_hash(claim).as_ref()),
        u64::MAX,
    )?;
    expected_fee_payment
        .validate()
        .map_err(|error| eyre!("invalid requested faucet fee payment: {error}"))?;
    prepared
        .fee_payment
        .validate()
        .map_err(|error| eyre!("invalid prepared faucet fee payment: {error}"))?;
    validate_prepared_mutation_binding(
        &prepared.binding,
        AccountFaucetPreparedTransactionV1::OPERATION,
        false,
    )?;
    validate_account_faucet_claim(claim)?;
    if prepared.schema != AccountFaucetPreparedTransactionV1::SCHEMA
        || prepared.operation != AccountFaucetPreparedTransactionV1::OPERATION
        || &prepared.binding != binding
        || &prepared.claim != claim
        || prepared.semantic_hash_hex != hex::encode(faucet_claim_hash(claim).as_ref())
        || prepared.account_id != claim.account_id
        || prepared.asset_definition_id != policy.asset_definition_id().to_string()
        || &prepared.amount != policy.amount()
    {
        return Err(eyre!(
            "prepared faucet envelope differs from its exact claim, binding, or trusted policy"
        ));
    }
    verify_prepared_payload_signature(
        &AccountFaucetPreparedSignaturePayloadV1::from(prepared),
        &prepared.server_signature,
        policy.faucet_authority(),
    )?;
    let transaction = decode_canonical_prepared_transaction(
        &prepared.transaction_hash_hex,
        &prepared.signed_transaction_wire_hex,
        &prepared.signed_transaction_wire_sha256,
    )?;

    validate_public_prepared_transaction_lifetime(&transaction, binding)?;
    let expected_metadata = expected_prepared_transaction_metadata(
        binding,
        AccountFaucetPreparedTransactionV1::OPERATION,
        &prepared.semantic_hash_hex,
    )?;
    if transaction.metadata() != &expected_metadata {
        return Err(eyre!(
            "prepared faucet transaction metadata differs from its exact binding and operation"
        ));
    }
    if transaction.network_id() != Some(&expected_network_id)
        || transaction.authority() != policy.faucet_authority()
        || transaction.payload().fee_payment != prepared.fee_payment
        || !expected_fee_payment.has_same_payer_and_gas_bound(&prepared.fee_payment)
    {
        return Err(eyre!(
            "prepared faucet transaction network, authority, or fee intent was substituted"
        ));
    }
    validate_faucet_transaction_identity(prepared, &transaction, policy)?;
    Ok(transaction)
}

/// Authenticate a nonterminal onboarding proof requirement without constructing a signing client.
///
/// Success authenticates only the exact request, receipt, reset binding, and Torii result. It does
/// not prove current ledger state; callers must obtain one fresh atomic account-and-alias
/// observation before terminalizing the operation.
///
/// # Errors
/// Returns an error for a substituted request or result, a network mismatch, noncanonical fields,
/// or an invalid receipt or prepared-result signature.
pub fn verify_account_onboarding_proof_required_result_v1(
    expected_network_id: NetworkId,
    request: &AccountOnboardingPlanRequestV1,
    proof_required: &AccountOnboardingProofRequiredPrepareResponseV1,
    receipt: &AccountOnboardingPlanReceiptV1,
    binding: &PreparedOperationBindingV1,
) -> Result<()> {
    validate_prepared_semantic_binding(
        binding,
        &hex::encode(receipt.plan_hash.as_ref()),
        receipt.body.valid_until_ms,
    )?;
    validate_prepared_mutation_binding(
        &proof_required.binding,
        AccountOnboardingPreparedTransactionV1::OPERATION,
        false,
    )?;
    if proof_required.schema != AccountOnboardingProofRequiredPrepareResponseV1::SCHEMA
        || proof_required.operation != AccountOnboardingPreparedTransactionV1::OPERATION
        || proof_required.outcome != AccountOnboardingProofRequiredPrepareResponseV1::OUTCOME
        || proof_required.proof_kind != AccountOnboardingProofRequiredPrepareResponseV1::PROOF_KIND
        || &proof_required.binding != binding
        || proof_required.semantic_hash_hex != hex::encode(receipt.plan_hash.as_ref())
        || proof_required.account_id != receipt.body.request.account_id
        || proof_required.alias != receipt.body.request.alias
        || proof_required.disposition != AliasPlanDispositionV1::NoOp
    {
        return Err(eyre!(
            "proof-required onboarding result differs from its exact receipt or binding"
        ));
    }
    decode_and_verify_account_onboarding_plan_for_request(expected_network_id, request, receipt)?;
    verify_prepared_payload_signature(
        &AccountOnboardingProofRequiredSignaturePayloadV1::from(proof_required),
        &proof_required.server_signature,
        &receipt.body.authority,
    )
}

fn parse_prepared_submit_response(
    response: &Response<Vec<u8>>,
    expected_binding: &PreparedOperationBindingV1,
    expected_operation: &str,
    expected_hash: &str,
) -> Result<PreparedTransactionSubmitResponseV1> {
    if !matches!(response.status(), StatusCode::OK | StatusCode::ACCEPTED) {
        return Err(eyre!(
            "prepared transaction submission failed with HTTP status {}",
            response.status()
        ));
    }
    let wire: PreparedTransactionSubmitResponseWireV1 =
        norito::json::from_slice(response.body())
            .wrap_err("decode prepared transaction submit response")?;
    if wire.schema != "iroha.prepared-transaction-submit.v1"
        || &wire.binding != expected_binding
        || wire.operation != expected_operation
        || wire.transaction_hash_hex != expected_hash
        || !lower_hex_with_len(&wire.transaction_hash_hex, 64)
    {
        return Err(eyre!(
            "prepared transaction submit response is not bound to the exact envelope"
        ));
    }
    let outcome = match wire.outcome.as_str() {
        "Applied" => PreparedTransactionOutcomeV1::Applied,
        "Pending" => PreparedTransactionOutcomeV1::Pending,
        "Rejected" => PreparedTransactionOutcomeV1::Rejected,
        other => {
            return Err(eyre!(
                "prepared transaction submit response has unknown outcome `{other}`"
            ));
        }
    };
    if response.status() == StatusCode::ACCEPTED && outcome != PreparedTransactionOutcomeV1::Pending
    {
        return Err(eyre!(
            "HTTP 202 prepared transaction response must have outcome Pending"
        ));
    }
    Ok(PreparedTransactionSubmitResponseV1 {
        binding: wire.binding,
        operation: wire.operation,
        transaction_hash_hex: wire.transaction_hash_hex,
        outcome,
    })
}

fn validate_account_onboarding_token(token: &str) -> Result<&str> {
    let bytes = token.as_bytes();
    if !(32..=256).contains(&bytes.len()) || !bytes.iter().all(|byte| (0x21..=0x7e).contains(byte))
    {
        return Err(eyre!(
            "account onboarding token must contain 32 through 256 printable ASCII bytes without spaces"
        ));
    }
    Ok(token)
}
/// Unsigned verifying-key registry transaction returned for local signing.
#[derive(Clone, Debug, PartialEq, Eq, JsonSerialize, JsonDeserialize)]
#[norito(deny_unknown_fields)]
pub struct ZkVkTransactionDraft {
    /// Always `false`; Torii has not submitted this transaction.
    pub submitted: bool,
    /// Canonical Norito `TransactionPayload` bytes encoded as padded base64.
    pub transaction_payload_b64: String,
    /// Exact transaction-payload prehash encoded as padded base64.
    pub signing_message_b64: String,
}
/// Filters for `/v1/zk/proofs` list/count endpoints.
#[derive(Debug, Default, Clone)]
pub struct ZkProofsFilter<'a> {
    /// Exact backend (e.g., `pipa-r/pasta`).
    pub backend: Option<&'a str>,
    /// Status filter (`Submitted`, `Verified`, `Rejected`).
    pub status: Option<&'a str>,
    /// Require a specific ZK1 TLV tag (4 ASCII characters).
    pub has_tag: Option<&'a str>,
    /// Minimum `verified_at_height` (inclusive).
    pub verified_from_height: Option<u64>,
    /// Maximum `verified_at_height` (inclusive).
    pub verified_until_height: Option<u64>,
    /// Maximum number of results (server caps at 1000).
    pub limit: Option<u32>,
    /// Offset for server-side pagination.
    pub offset: Option<u32>,
    /// Sort order (`asc` or `desc`).
    pub order: Option<&'a str>,
    /// Return only `{ backend, hash }` objects when true.
    pub ids_only: Option<bool>,
}
impl ZkProofsFilter<'_> {
    fn apply(&self, mut req: DefaultRequestBuilder) -> DefaultRequestBuilder {
        if let Some(v) = self.backend {
            req = req.param("backend", &v);
        }
        if let Some(v) = self.status {
            req = req.param("status", &v);
        }
        if let Some(v) = self.has_tag {
            req = req.param("has_tag", &v);
        }
        if let Some(v) = self.verified_from_height {
            req = req.param("verified_from_height", &v);
        }
        if let Some(v) = self.verified_until_height {
            req = req.param("verified_until_height", &v);
        }
        if let Some(v) = self.limit {
            req = req.param("limit", &v);
        }
        if let Some(v) = self.offset {
            req = req.param("offset", &v);
        }
        if let Some(v) = self.order {
            req = req.param("order", &v);
        }
        if let Some(true) = self.ids_only {
            req = req.param("ids_only", &"true");
        }
        req
    }
}
fn validate_zk_proofs_filter(filter: &ZkProofsFilter<'_>) -> Result<()> {
    if let Some(backend) = filter.backend {
        require_verifier_backend_registry_label_v1(backend, "zk proofs filter backend")?;
    }
    Ok(())
}
fn validate_zk_vk_submission_json(
    value: &norito::json::Value,
    context: &str,
    require_gas_schedule_id: bool,
) -> Result<()> {
    const FIELDS: [&str; 17] = [
        "authority",
        "backend",
        "name",
        "version",
        "circuit_id",
        "public_inputs_schema_hash_hex",
        "curve",
        "gas_schedule_id",
        "vk_len",
        "max_proof_bytes",
        "metadata_uri_cid",
        "vk_bytes_cid",
        "activation_height",
        "withdraw_height",
        "commitment_hex",
        "vk_bytes",
        "status",
    ];
    let object = require_json_object(value, context)?;
    if let Some(field) = object
        .keys()
        .find(|field| !FIELDS.contains(&field.as_str()))
    {
        return Err(eyre!("{context} contains unknown field {field}"));
    }
    let backend = require_json_backend_field(object, "backend", &format!("{context}.backend"))?;
    require_json_vk_name_field(object, "name", &format!("{context}.name"))?;
    let authority =
        require_json_non_empty_string_field(object, "authority", &format!("{context}.authority"))?;
    ensure_canonical_i105_account_id(authority, &format!("{context}.authority"))?;
    require_json_positive_u32_field(object, "version", &format!("{context}.version"))?;
    require_json_non_empty_string_field(object, "circuit_id", &format!("{context}.circuit_id"))?;
    require_json_hex32_field(
        object,
        "public_inputs_schema_hash_hex",
        &format!("{context}.public_inputs_schema_hash_hex"),
    )?;
    if require_gas_schedule_id {
        require_json_non_empty_string_field(
            object,
            "gas_schedule_id",
            &format!("{context}.gas_schedule_id"),
        )?;
    } else {
        validate_optional_json_non_empty_string_field(
            object,
            "gas_schedule_id",
            &format!("{context}.gas_schedule_id"),
        )?;
    }
    validate_optional_json_non_empty_string_field(object, "curve", &format!("{context}.curve"))?;
    validate_optional_json_non_empty_string_field(
        object,
        "metadata_uri_cid",
        &format!("{context}.metadata_uri_cid"),
    )?;
    validate_optional_json_non_empty_string_field(
        object,
        "vk_bytes_cid",
        &format!("{context}.vk_bytes_cid"),
    )?;
    validate_optional_json_u32_field(
        object,
        "max_proof_bytes",
        &format!("{context}.max_proof_bytes"),
    )?;
    validate_optional_json_status_field(object, "status", &format!("{context}.status"))?;
    validate_optional_json_height_range(object, context)?;
    validate_optional_json_vk_submission_bytes(object, backend, context)?;
    Ok(())
}
#[derive(Clone, Copy)]
enum ZkVkDraftOperation {
    Register,
    Update,
}
fn decode_canonical_zk_vk_base64(
    value: &str,
    max_decoded_bytes: usize,
    context: &str,
) -> Result<Vec<u8>> {
    let max_encoded_bytes = max_decoded_bytes.div_ceil(3).saturating_mul(4);
    if value.len() > max_encoded_bytes {
        return Err(eyre!("{context} exceeds its decoded byte limit"));
    }
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(value)
        .wrap_err_with(|| format!("{context} must be canonical padded base64"))?;
    if bytes.is_empty()
        || bytes.len() > max_decoded_bytes
        || base64::engine::general_purpose::STANDARD.encode(&bytes) != value
    {
        return Err(eyre!("{context} must be non-empty canonical padded base64"));
    }
    Ok(bytes)
}
fn decode_zk_vk_hex32(value: &str, context: &str) -> Result<[u8; 32]> {
    let normalized = normalize_hex32_lower(value, context)?;
    let bytes = hex::decode(normalized).wrap_err_with(|| format!("decode {context}"))?;
    let mut output = [0_u8; 32];
    output.copy_from_slice(&bytes);
    Ok(output)
}
fn expected_zk_vk_len(object: &norito::json::Map, vk_bytes: Option<&[u8]>) -> Result<u32> {
    if let Some(bytes) = vk_bytes {
        u32::try_from(bytes.len()).wrap_err("verifying-key draft key length exceeds u32")
    } else {
        validate_optional_json_positive_u32_field(
            object,
            "vk_len",
            "verifying-key draft request.vk_len",
        )?
        .ok_or_else(|| eyre!("verifying-key draft request.vk_len is required"))
    }
}
fn expected_zk_vk_status(
    object: &norito::json::Map,
) -> Result<iroha_data_model::confidential::ConfidentialStatus> {
    use iroha_data_model::confidential::ConfidentialStatus;
    match object.get("status").and_then(norito::json::Value::as_str) {
        None | Some("Active") => Ok(ConfidentialStatus::Active),
        Some("Proposed") => Ok(ConfidentialStatus::Proposed),
        Some("Withdrawn") => Ok(ConfidentialStatus::Withdrawn),
        Some(status) => Err(eyre!(
            "verifying-key draft request uses invalid status {status}"
        )),
    }
}
fn expected_zk_vk_record_from_request(
    request: &norito::json::Value,
) -> Result<iroha_data_model::proof::VerifyingKeyRecord> {
    use iroha_data_model::proof::{VerifyingKeyBox, VerifyingKeyRecord};
    let object = require_json_object(request, "verifying-key draft request")?;
    let backend =
        require_json_backend_field(object, "backend", "verifying-key draft request.backend")?;
    let version =
        require_json_positive_u32_field(object, "version", "verifying-key draft request.version")?;
    let circuit_id = require_json_non_empty_string_field(
        object,
        "circuit_id",
        "verifying-key draft request.circuit_id",
    )?;
    let schema_hash = decode_zk_vk_hex32(
        require_json_non_empty_string_field(
            object,
            "public_inputs_schema_hash_hex",
            "verifying-key draft request.public_inputs_schema_hash_hex",
        )?,
        "verifying-key draft request.public_inputs_schema_hash_hex",
    )?;
    let backend_tag = iroha_data_model::zk::verifier_backend_registry_tag_v1(backend)
        .ok_or_else(|| eyre!("verifying-key draft request uses an unsupported backend"))?;
    let vk_bytes = validate_optional_json_base64_bytes_field(
        object,
        "vk_bytes",
        "verifying-key draft request.vk_bytes",
    )?;
    let commitment = match (
        vk_bytes.as_ref(),
        object
            .get("commitment_hex")
            .and_then(norito::json::Value::as_str),
    ) {
        (Some(bytes), _) => decode_zk_vk_hex32(
            &zk_vk_commitment_hex(backend, bytes)?,
            "verifying-key draft computed commitment",
        )?,
        (None, Some(commitment)) => {
            decode_zk_vk_hex32(commitment, "verifying-key draft request.commitment_hex")?
        }
        (None, None) => {
            return Err(eyre!(
                "verifying-key draft request must provide commitment material"
            ));
        }
    };
    let vk_len = expected_zk_vk_len(object, vk_bytes.as_deref())?;
    let mut record = VerifyingKeyRecord::new_with_owner(
        version,
        circuit_id,
        None,
        "core",
        backend_tag,
        object
            .get("curve")
            .and_then(norito::json::Value::as_str)
            .unwrap_or("unknown"),
        schema_hash,
        commitment,
    );
    record.vk_len = vk_len;
    record.max_proof_bytes = validate_optional_json_u32_field(
        object,
        "max_proof_bytes",
        "verifying-key draft request.max_proof_bytes",
    )?
    .unwrap_or(0);
    record.gas_schedule_id = object
        .get("gas_schedule_id")
        .and_then(norito::json::Value::as_str)
        .map(str::to_owned);
    record.metadata_uri_cid = object
        .get("metadata_uri_cid")
        .and_then(norito::json::Value::as_str)
        .map(str::to_owned);
    record.vk_bytes_cid = object
        .get("vk_bytes_cid")
        .and_then(norito::json::Value::as_str)
        .map(str::to_owned);
    record.activation_height = object
        .get("activation_height")
        .and_then(norito::json::Value::as_u64);
    record.withdraw_height = object
        .get("withdraw_height")
        .and_then(norito::json::Value::as_u64);
    record.key = vk_bytes.map(|bytes| VerifyingKeyBox::new(backend.into(), bytes));
    record.status = expected_zk_vk_status(object)?;
    Ok(record)
}
fn decode_zk_vk_transaction_draft(
    body: &[u8],
    request: &norito::json::Value,
    expected_network_id: &NetworkId,
    operation: ZkVkDraftOperation,
) -> Result<ZkVkTransactionDraft> {
    let draft: ZkVkTransactionDraft = norito::json::from_slice(body)
        .wrap_err("decode verifying-key transaction draft response")?;
    if draft.submitted {
        return Err(eyre!(
            "verifying-key transaction draft must not claim server submission"
        ));
    }
    let payload_bytes = decode_canonical_zk_vk_base64(
        &draft.transaction_payload_b64,
        ZK_VK_DRAFT_MAX_TRANSACTION_PAYLOAD_BYTES,
        "verifying-key draft transaction_payload_b64",
    )?;
    let builder = TransactionBuilder::decode_payload(&payload_bytes)
        .wrap_err("decode canonical verifying-key transaction payload")?;
    let signing_message = decode_canonical_zk_vk_base64(
        &draft.signing_message_b64,
        Hash::LENGTH,
        "verifying-key draft signing_message_b64",
    )?;
    if signing_message.as_slice() != HashOf::new(builder.payload()).as_ref() {
        return Err(eyre!(
            "verifying-key draft signing_message_b64 does not match the transaction payload"
        ));
    }
    let object = require_json_object(request, "verifying-key draft request")?;
    let authority = parse_canonical_i105_account_id(
        require_json_non_empty_string_field(
            object,
            "authority",
            "verifying-key draft request.authority",
        )?,
        "verifying-key draft request.authority",
    )?;
    if builder.payload().domain
        != iroha_data_model::transaction::TransactionDomain::Network(*expected_network_id)
        || builder.payload().authority != authority
    {
        return Err(eyre!(
            "verifying-key draft transaction payload changed the requested network or authority"
        ));
    }
    let backend =
        require_json_backend_field(object, "backend", "verifying-key draft request.backend")?;
    let name = require_json_vk_name_field(object, "name", "verifying-key draft request.name")?;
    let expected_record = expected_zk_vk_record_from_request(request)?;
    let iroha_data_model::transaction::Executable::Instructions(instructions) =
        &builder.payload().instructions
    else {
        return Err(eyre!(
            "verifying-key draft transaction payload must contain native instructions"
        ));
    };
    if instructions.len() != 1 {
        return Err(eyre!(
            "verifying-key draft transaction payload must contain exactly one instruction"
        ));
    }
    let id_matches = match operation {
        ZkVkDraftOperation::Register => instructions[0]
            .as_any()
            .downcast_ref::<iroha_data_model::isi::verifying_keys::RegisterVerifyingKey>()
            .is_some_and(|instruction| {
                instruction.id.backend.as_str() == backend
                    && instruction.id.name == name
                    && instruction.record == expected_record
            }),
        ZkVkDraftOperation::Update => instructions[0]
            .as_any()
            .downcast_ref::<iroha_data_model::isi::verifying_keys::UpdateVerifyingKey>()
            .is_some_and(|instruction| {
                instruction.id.backend.as_str() == backend
                    && instruction.id.name == name
                    && instruction.record == expected_record
            }),
    };
    if !id_matches {
        return Err(eyre!(
            "verifying-key draft transaction payload does not contain the requested registry operation"
        ));
    }
    Ok(draft)
}
fn require_json_object<'a>(
    value: &'a norito::json::Value,
    context: &str,
) -> Result<&'a norito::json::Map> {
    value
        .as_object()
        .ok_or_else(|| eyre!("{context} must be a JSON object"))
}
fn require_json_backend_field<'a>(
    object: &'a norito::json::Map,
    field: &str,
    context: &str,
) -> Result<&'a str> {
    let backend = object
        .get(field)
        .and_then(norito::json::Value::as_str)
        .ok_or_else(|| eyre!("{context} must be a string"))?;
    require_verifier_backend_registry_label_v1(backend, context)
}
fn require_json_non_empty_string_field<'a>(
    object: &'a norito::json::Map,
    field: &str,
    context: &str,
) -> Result<&'a str> {
    let value = object
        .get(field)
        .and_then(norito::json::Value::as_str)
        .ok_or_else(|| eyre!("{context} must be a string"))?;
    if value.trim().is_empty() {
        return Err(eyre!("{context} must be non-empty"));
    }
    Ok(value)
}
fn require_json_vk_name_field<'a>(
    object: &'a norito::json::Map,
    field: &str,
    context: &str,
) -> Result<&'a str> {
    let value = require_json_non_empty_string_field(object, field, context)?;
    if value.contains(':') {
        return Err(eyre!("{context} must not contain ':'"));
    }
    Ok(value)
}
fn validate_optional_json_non_empty_string_field(
    object: &norito::json::Map,
    field: &str,
    context: &str,
) -> Result<()> {
    match object.get(field) {
        None => Ok(()),
        Some(value) if value.is_null() => Ok(()),
        Some(_) => {
            require_json_non_empty_string_field(object, field, context)?;
            Ok(())
        }
    }
}
fn require_json_positive_u32_field(
    object: &norito::json::Map,
    field: &str,
    context: &str,
) -> Result<u32> {
    let value = object
        .get(field)
        .and_then(norito::json::Value::as_u64)
        .ok_or_else(|| eyre!("{context} must be a positive u32"))?;
    if value == 0 || value > u64::from(u32::MAX) {
        return Err(eyre!("{context} must be a positive u32"));
    }
    Ok(u32::try_from(value).expect("value is bounded to u32"))
}
fn validate_optional_json_positive_u32_field(
    object: &norito::json::Map,
    field: &str,
    context: &str,
) -> Result<Option<u32>> {
    let Some(value) = object.get(field) else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    let value = value
        .as_u64()
        .ok_or_else(|| eyre!("{context} must be a positive u32"))?;
    if value == 0 || value > u64::from(u32::MAX) {
        return Err(eyre!("{context} must be a positive u32"));
    }
    Ok(Some(u32::try_from(value).expect("value is bounded to u32")))
}
