fn canonicalize_uaid_literal(literal: &str, context: &str) -> Result<String> {
    if literal.is_empty() || literal.trim() != literal {
        return Err(eyre!(
            "{context} must be an exact canonical `uaid:<lowercase-hex>` literal"
        ));
    }
    let uaid = UniversalAccountId::from_str(literal).wrap_err_with(|| {
        format!("{context} must be an exact canonical `uaid:<lowercase-hex>` literal")
    })?;
    let canonical = uaid.to_string();
    if canonical != literal
        || !literal.as_bytes().last().is_some_and(|byte| {
            matches!(*byte, b'1' | b'3' | b'5' | b'7' | b'9' | b'b' | b'd' | b'f')
        })
    {
        return Err(eyre!(
            "{context} must be a canonical UAID with its least significant bit set to 1"
        ));
    }
    Ok(canonical)
}
fn canonicalize_hex32_literal(literal: &str, context: &str) -> Result<String> {
    let trimmed = literal.trim();
    if trimmed.len() != 64 || !trimmed.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err(eyre!(
            "{context} must contain exactly 64 hexadecimal characters"
        ));
    }
    Ok(trimmed.to_ascii_lowercase())
}
fn validate_multisig_read_selector(
    multisig_account_id: Option<&iroha_data_model::account::AccountId>,
    multisig_account_alias: Option<&str>,
) -> Result<()> {
    match (multisig_account_id, multisig_account_alias) {
        (Some(_), None) => Ok(()),
        (None, Some(alias)) if !alias.is_empty() && alias.trim() == alias => Ok(()),
        (None, Some(_)) => Err(eyre!(
            "multisig_account_alias must be an exact non-empty canonical literal"
        )),
        _ => Err(eyre!(
            "exactly one of multisig_account_id or multisig_account_alias must be set"
        )),
    }
}
fn validate_multisig_proposal_read_selector(proposal_id: &str) -> Result<()> {
    proposal_id
        .parse::<iroha_executor_data_model::isi::multisig::MultisigProposalId>()
        .wrap_err("proposal_id must be a canonical occurrence ID")?;
    Ok(())
}

fn validate_multisig_proposal_binding(
    network_id: &NetworkId,
    account_id: &AccountId,
    proposal_id: &str,
    instructions_hash: &str,
    proposal: &iroha_executor_data_model::isi::multisig::MultisigProposalValue,
) -> Result<()> {
    use iroha_executor_data_model::isi::multisig::MultisigProposalId;
    validate_multisig_proposal_read_selector(proposal_id)?;
    let expected = MultisigProposalId::derive(network_id, account_id, &proposal.proposal_nonce);
    if proposal.network_id != *network_id
        || proposal.proposal_id != expected
        || proposal_id != expected.to_string()
        || instructions_hash != hex::encode(HashOf::new(&proposal.instructions).as_ref())
        || proposal.proposed_at_ms >= proposal.expires_at_ms
    {
        return Err(eyre!(
            "multisig proposal occurrence or content binding differs from its native original"
        ));
    }
    Ok(())
}

fn require_string<'a>(value: Option<&'a JsonValue>, context: &str) -> Result<&'a str> {
    match value {
        Some(JsonValue::String(text)) => Ok(text),
        Some(other) => Err(eyre!("{context} must be a string (got {other:?})")),
        None => Err(eyre!("{context} is missing")),
    }
}
fn require_exact_fields(map: &JsonMap, fields: &[&str], context: &str) -> Result<()> {
    let missing = fields
        .iter()
        .copied()
        .filter(|field| !map.contains_key(*field))
        .collect::<Vec<_>>();
    let unexpected = map
        .keys()
        .map(String::as_str)
        .filter(|field| !fields.contains(field))
        .collect::<Vec<_>>();
    if missing.is_empty() && unexpected.is_empty() {
        return Ok(());
    }
    Err(eyre!(
        "{context} must use the exact server fields (missing: {missing:?}; unexpected: {unexpected:?})"
    ))
}
fn parse_required_json_u64(value: Option<&JsonValue>, context: &str) -> Result<u64> {
    match value {
        Some(JsonValue::Number(number)) => number
            .as_u64()
            .ok_or_else(|| eyre!("{context} must be a non-negative JSON integer")),
        Some(other) => Err(eyre!(
            "{context} must be a non-negative JSON integer (got {other:?})"
        )),
        None => Err(eyre!("{context} is missing")),
    }
}
fn parse_required_nullable_json_u64(
    value: Option<&JsonValue>,
    context: &str,
) -> Result<Option<u64>> {
    match value {
        Some(JsonValue::Null) => Ok(None),
        Some(other) => parse_required_json_u64(Some(other), context).map(Some),
        None => Err(eyre!("{context} is missing")),
    }
}
fn parse_required_nullable_string(
    value: Option<&JsonValue>,
    context: &str,
) -> Result<Option<String>> {
    match value {
        Some(JsonValue::String(text)) => Ok(Some(text.to_owned())),
        Some(JsonValue::Null) => Ok(None),
        Some(other) => Err(eyre!("{context} must be a string or null (got {other:?})")),
        None => Err(eyre!("{context} is missing")),
    }
}
fn required_owned_array(value: Option<&JsonValue>, context: &str) -> Result<Vec<JsonValue>> {
    match value {
        Some(JsonValue::Array(items)) => Ok(items.clone()),
        Some(other) => Err(eyre!("{context} must be an array (got {other:?})")),
        None => Err(eyre!("{context} is missing")),
    }
}
fn canonical_account_array(value: Option<&JsonValue>, context: &str) -> Result<Vec<String>> {
    required_owned_array(value, context)?
        .into_iter()
        .enumerate()
        .map(|(index, entry)| {
            let JsonValue::String(literal) = entry else {
                return Err(eyre!("{context}[{index}] must be a string"));
            };
            iroha_data_model::account::AccountId::parse_encoded(&literal).map_err(|err| {
                eyre!("{context}[{index}] must be a canonical I105 account id: {err}")
            })?;
            Ok(literal)
        })
        .collect()
}
fn require_exact_lower_hex32_literal(literal: &str, context: &str) -> Result<String> {
    if literal.len() != 64
        || !literal
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(eyre!(
            "{context} must contain exactly 64 lowercase hexadecimal characters"
        ));
    }
    Ok(literal.to_owned())
}
fn parse_optional_string(value: Option<&JsonValue>, context: &str) -> Result<Option<String>> {
    match value {
        Some(JsonValue::String(text)) => Ok(Some(text.to_owned())),
        Some(JsonValue::Null) | None => Ok(None),
        Some(other) => Err(eyre!(
            "{context} must be a string when present (got {other:?})"
        )),
    }
}
fn signed_transaction_schema_hash_hex() -> String {
    hex::encode(norito::schema::identity::frame_hash::<SignedTransaction>())
}
fn parse_signed_transaction_schema_hash_hex(
    capabilities: &JsonValue,
) -> core::result::Result<String, TransactionSchemaCompatibilityError> {
    let expected = signed_transaction_schema_hash_hex();
    let field = "node capabilities signed_transaction_schema_hash_hex";
    let advertised = match parse_optional_string(
        capabilities.get("signed_transaction_schema_hash_hex"),
        field,
    ) {
        Ok(Some(value)) => value,
        Ok(None) => {
            return Err(TransactionSchemaCompatibilityError::Missing { expected });
        }
        Err(err) => {
            return Err(TransactionSchemaCompatibilityError::Invalid {
                expected,
                actual: None,
                details: err.to_string(),
            });
        }
    };
    if advertised.len() != 32 {
        return Err(TransactionSchemaCompatibilityError::Invalid {
            expected,
            actual: Some(advertised),
            details: "signed_transaction_schema_hash_hex must be 32 lowercase hex chars"
                .to_string(),
        });
    }
    if !advertised.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(TransactionSchemaCompatibilityError::Invalid {
            expected,
            actual: Some(advertised),
            details: "signed_transaction_schema_hash_hex must contain only hex digits".to_string(),
        });
    }
    if advertised.bytes().any(|byte| byte.is_ascii_uppercase()) {
        return Err(TransactionSchemaCompatibilityError::Invalid {
            expected,
            actual: Some(advertised),
            details: "signed_transaction_schema_hash_hex must be lowercase hex".to_string(),
        });
    }
    if advertised == expected {
        Ok(advertised)
    } else {
        Err(TransactionSchemaCompatibilityError::Mismatch {
            expected,
            actual: advertised,
        })
    }
}
fn parse_required_u64(value: Option<&JsonValue>, context: &str) -> Result<u64> {
    let Some(raw) = value else {
        return Err(eyre!("{context} is missing"));
    };
    parse_u64(raw, context)
}
fn parse_optional_u64(value: Option<&JsonValue>, context: &str) -> Result<Option<u64>> {
    match value {
        Some(JsonValue::Null) | None => Ok(None),
        Some(other) => parse_u64(other, context).map(Some),
    }
}
fn parse_u64(value: &JsonValue, context: &str) -> Result<u64> {
    match value {
        JsonValue::Number(number) => number
            .as_u64()
            .ok_or_else(|| eyre!("{context} must be a non-negative integer")),
        JsonValue::String(text) => text
            .parse::<u64>()
            .wrap_err_with(|| format!("{context} must be a non-negative integer string")),
        other => Err(eyre!(
            "{context} must be a non-negative integer (got {other:?})"
        )),
    }
}
fn parse_manifest(value: &JsonValue, context: &str) -> Result<AssetPermissionManifest> {
    norito::json::from_value(value.clone())
        .wrap_err_with(|| format!("{context} must be a valid AssetPermissionManifest"))
}
