    #[test]
    fn send_builder_enforces_alias_policy_for_stale_proof() {
        let now = unix_now_secs();
        let bundle = alias_proof_bundle(now.saturating_sub(900), now.saturating_sub(300));
        let proof_b64 = alias_proof_base64(&bundle);
        let status_label = default_alias_policy().evaluate(&bundle, now).status_label();
        let response = HttpResponse::builder()
            .status(StatusCode::OK)
            .header("content-type", APPLICATION_JSON)
            .header(HEADER_SORA_NAME, "docs/stale")
            .header(HEADER_SORA_PROOF, proof_b64)
            .header(HEADER_SORA_PROOF_STATUS, status_label)
            .body(b"{}".to_vec())
            .expect("response build");
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        with_mock_http(respond_with(&store, response), |mock_transport| {
            let client =
                client_with_base_url(base_url()).with_test_http_transport(mock_transport.clone());
            let builder = client.default_request(HttpMethod::GET, base_url());
            let err = client
                .send_builder(builder)
                .expect_err("stale alias proof should trigger send_builder error");
            assert!(
                err.to_string().contains("alias proof"),
                "expected alias proof rejection, got {err}"
            );
        });
    }
    #[test]
    fn build_register_manifest_instruction_contains_exact_fields() {
        let descriptor = sorafs_manifest::chunker_registry::default_descriptor();
        let chunking_profile = sorafs_manifest::ChunkingProfileV1::from_descriptor(descriptor);
        let chunk_digest = [0xCD; 32];
        let manifest = sorafs_manifest::ManifestBuilder::new()
            .root_cid(sorafs_manifest::canonical_manifest_root_cid([0x01; 32]))
            .dag_codec(sorafs_manifest::DagCodecId(0x71))
            .chunking_profile(chunking_profile)
            .chunk_digest_sha3_256(chunk_digest)
            .por_root([0xD1; 32])
            .content_length(1_024)
            .car_digest([0xAB; 32])
            .car_size(2_048)
            .pin_policy(sorafs_manifest::PinPolicy {
                min_replicas: 3,
                storage_class: sorafs_manifest::StorageClass::Warm,
                retention_epoch: 77,
            })
            .build()
            .expect("manifest build");
        let alias_bytes = *b"alias-proof";
        let alias = SorafsPinAlias {
            namespace: "sora",
            name: "docs",
            proof: alias_bytes.as_ref(),
        };
        let successor = [0x11; 32];
        let manifest_payload = manifest.encode().expect("canonical manifest encoding");
        let instruction = Client::build_sorafs_pin_register_instruction(SorafsPinRegisterArgs {
            manifest_payload: &manifest_payload,
            alias: Some(alias),
            successor_of: Some(successor),
        })
        .expect("instruction build succeeds");
        assert_eq!(instruction.manifest_payload, manifest_payload);
        let alias = instruction.alias.expect("alias binding");
        assert_eq!(alias.namespace, "sora");
        assert_eq!(alias.name, "docs");
        assert_eq!(alias.proof, alias_bytes);
        assert_eq!(
            instruction.successor_of.expect("successor").as_bytes(),
            &successor
        );
    }
    #[test]
    fn build_register_manifest_instruction_uses_exact_canonical_manifest_payload() {
        let descriptor = sorafs_manifest::chunker_registry::default_descriptor();
        let manifest = sorafs_manifest::ManifestBuilder::new()
            .root_cid(sorafs_manifest::canonical_manifest_root_cid([0x05; 32]))
            .dag_codec(sorafs_manifest::DagCodecId(0x71))
            .chunking_profile(sorafs_manifest::ChunkingProfileV1::from_descriptor(
                descriptor,
            ))
            .chunk_digest_sha3_256([0xCC; 32])
            .por_root([0xD2; 32])
            .content_length(32)
            .car_digest([0x44; 32])
            .car_size(64)
            .pin_policy(sorafs_manifest::PinPolicy::default())
            .build()
            .expect("manifest build");
        let explicit_manifest_payload = manifest.encode().expect("canonical manifest encoding");
        let instruction = Client::build_sorafs_pin_register_instruction(SorafsPinRegisterArgs {
            manifest_payload: &explicit_manifest_payload,
            alias: None,
            successor_of: None,
        })
        .expect("instruction build succeeds");
        assert_eq!(instruction.manifest_payload, explicit_manifest_payload);
        assert!(instruction.alias.is_none());
        assert!(instruction.successor_of.is_none());
    }
