    #[test]
    fn build_register_manifest_instruction_rejects_malformed_aliases() {
        let manifest = pin_register_test_manifest();
        let manifest_payload = manifest.encode().expect("canonical manifest encoding");
        let oversized_segment = "a".repeat(SORAFS_PIN_REGISTER_MAX_ALIAS_SEGMENT_BYTES + 1);
        let oversized_proof = vec![0_u8; SORAFS_PIN_REGISTER_MAX_ALIAS_PROOF_BYTES + 1];
        let cases = [
            SorafsPinAlias {
                namespace: "Sora",
                name: "docs",
                proof: b"proof",
            },
            SorafsPinAlias {
                namespace: "sora",
                name: oversized_segment.as_str(),
                proof: b"proof",
            },
            SorafsPinAlias {
                namespace: "sora",
                name: "docs",
                proof: b"",
            },
            SorafsPinAlias {
                namespace: "sora",
                name: "docs",
                proof: &oversized_proof,
            },
        ];
        for alias in cases {
            let _ = Client::build_sorafs_pin_register_instruction(SorafsPinRegisterArgs {
                manifest_payload: &manifest_payload,
                alias: Some(alias),
                successor_of: None,
            })
            .expect_err("malformed alias must fail closed");
        }
    }
