    fn transaction_hash(seed: u8) -> HashOf<SignedTransaction> {
        HashOf::from_untyped_unchecked(Hash::prehashed([seed; Hash::LENGTH]))
    }
    fn committed_transaction_details_fixture(
        client: &Client,
        result: iroha_data_model::transaction::TransactionResult,
    ) -> (SignedTransaction, PipelineTransactionDetailsResponse) {
        use crate::crypto::MerkleProof;
        use iroha_data_model::query::CommittedTransaction;
        let signed = {
            let account = client
                .account_client()
                .expect("bind committed-transaction fixture account");
            account
                .prepare_transaction(AccountTransactionDraft::new(
                    Vec::<InstructionBox>::new(),
                    iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
                    Metadata::default(),
                ))
                .and_then(|payload| account.sign_transaction(payload))
        }
        .expect("build committed-transaction fixture");
        let entrypoint = TransactionEntrypoint::External(signed.clone());
        let entrypoint_hash = signed.hash_as_entrypoint();
        assert_eq!(entrypoint.hash(), entrypoint_hash);
        let output = iroha_data_model::block::execution_output::ExecutionOutputV1::Network(
            iroha_data_model::block::execution_output::NetworkExecutionOutputV1 {
                input_index: 0,
                result,
                completions: Vec::new(),
            },
        );
        let transaction = CommittedTransaction {
            block_hash: HashOf::from_untyped_unchecked(Hash::prehashed([0x77; Hash::LENGTH])),
            entrypoint_hash,
            entrypoint_proof: MerkleProof::from_audit_path(0, Vec::new()),
            entrypoint,
            output_hash: HashOf::new(&output),
            output_proof: MerkleProof::from_audit_path(0, Vec::new()),
            output,
        };
        (
            signed,
            PipelineTransactionDetailsResponse {
                hash: entrypoint_hash.to_string(),
                transaction,
            },
        )
    }
    fn captured_pipeline_status(
        seed: u8,
        response: HttpResponse<Vec<u8>>,
        confirmation: bool,
    ) -> (Result<Option<TxConfirmationStatus>>, Vec<RequestSnapshot>) {
        capture_requests(response, |mock_transport| {
            let client =
                client_with_base_url(base_url()).with_test_http_transport(mock_transport.clone());
            mark_data_model_compatible(&client);

            let hash = transaction_hash(seed);
            if confirmation {
                client.transaction_confirmation_status(hash)
            } else {
                client.transaction_pipeline_status(hash)
            }
        })
    }
    fn pipeline_response(
        hash: &str,
        status: &Value,
        scope: &str,
        resolved_from: &str,
    ) -> HttpResponse<Vec<u8>> {
        let payload = norito::json!({
            "hash": hash,
            "status": status,
            "scope": scope,
            "resolved_from": resolved_from
        });
        json_response(
            StatusCode::OK,
            &norito::json::to_string(&payload).expect("status payload"),
        )
    }
    fn assert_request_paths(snapshots: &[RequestSnapshot], expected: &[&str]) {
        assert_eq!(snapshots.len(), expected.len());
        for (snapshot, path) in snapshots.iter().zip(expected) {
            assert_eq!(snapshot.url.path(), *path);
        }
    }
    pub(super) fn assert_status_scope(snapshot: &RequestSnapshot, expected: &str) {
        assert_eq!(
            snapshot
                .url
                .query_pairs()
                .find(|(key, _)| key == "scope")
                .map(|(_, value)| value.to_string()),
            Some(expected.to_owned())
        );
    }
    pub(super) fn scoped_pipeline_absence(
        hash: &HashOf<SignedTransaction>,
    ) -> HttpResponse<Vec<u8>> {
        let envelope = iroha_torii_shared::ErrorEnvelope::new(
            iroha_torii_shared::PIPELINE_TRANSACTION_STATUS_NOT_FOUND_CODE,
            "Missing status.",
        )
        .with_details(iroha_torii_shared::ErrorDetails {
            pipeline_transaction_status_not_found: Some(
                iroha_torii_shared::PipelineTransactionStatusNotFoundV1::new(hash, "global"),
            ),
            ..iroha_torii_shared::ErrorDetails::default()
        });
        json_response(
            StatusCode::NOT_FOUND,
            &norito::json::to_json(&envelope).expect("typed absence"),
        )
    }
    #[test]
    fn pipeline_status_404_returns_none_from_exact_global_query() {
        let (result, snapshots) = captured_pipeline_status(
            0x11,
            scoped_pipeline_absence(&transaction_hash(0x11)),
            false,
        );
        assert!(
            captured_pipeline_status(0x11, empty_response(StatusCode::NOT_FOUND), false)
                .0
                .is_err(),
            "untyped404 cannot establish absence"
        );
        let status = result.expect("pipeline status query");
        assert!(status.is_none());
        assert_request_paths(&snapshots, &["/v1/pipeline/transactions/status"]);
        assert_status_scope(&snapshots[0], "global");
    }
