    #[derive(Clone, Copy)]
    enum StatusResponseRequest {
        Default,
        Local,
        Global,
        AsyncGlobal,
        AsyncLocal,
    }
    fn typed_status_response_snapshot(
        seed: u8,
        kind: &str,
        block_height: Option<u64>,
        scope: &str,
        resolved_from: &str,
        request: StatusResponseRequest,
    ) -> RequestSnapshot {
        use iroha_torii_shared::{PipelineTransactionStatus, PipelineTransactionStatusResponse};
        let hash = transaction_hash(seed);
        let payload = PipelineTransactionStatusResponse::new(
            hash.to_string(),
            PipelineTransactionStatus {
                kind: kind.to_owned(),
                block_height,
            },
            scope.to_owned(),
            resolved_from.to_owned(),
        );
        let body = norito::json::to_string(
            &norito::json::to_value(&payload).expect("status payload value"),
        )
        .expect("status payload");
        let (decoded, snapshot) =
            capture_request(json_response(StatusCode::OK, &body), |mock_transport| {
                let client = client_with_base_url(base_url())
                    .with_test_http_transport(mock_transport.clone());
                match request {
                    StatusResponseRequest::Default => client.get_transaction_status_response(hash),
                    StatusResponseRequest::Local => {
                        client.get_transaction_status_response_local(hash)
                    }
                    StatusResponseRequest::Global => {
                        client.get_transaction_status_response_global(hash)
                    }
                    StatusResponseRequest::AsyncLocal => {
                        tokio::runtime::Builder::new_current_thread()
                            .enable_all()
                            .build()
                            .expect("status runtime")
                            .block_on(client.fetch_transaction_status_response_local(hash))
                    }
                    StatusResponseRequest::AsyncGlobal => {
                        tokio::runtime::Builder::new_current_thread()
                            .enable_all()
                            .build()
                            .expect("status runtime")
                            .block_on(client.fetch_transaction_status_response_global(hash))
                    }
                }
            });
        assert_eq!(
            decoded
                .expect("transaction status response")
                .expect("status payload"),
            payload
        );
        assert_eq!(
            snapshot.max_response_bytes,
            PIPELINE_TRANSACTION_STATUS_RESPONSE_MAX_BYTES
        );
        snapshot
    }
