    /// Poll exact global pipeline status until state-resolved `Applied` finality.
    ///
    /// State-resolved `Rejected` and `Expired` are fixed failure outcomes. Cached or queued
    /// terminal hints and every non-final status continue polling; callers cannot weaken this
    /// first-release finality rule. HTTP 429 backpressure repeats only the status read within
    /// the original deadline, respecting Torii's delta-seconds `Retry-After` when present.
    /// It never resubmits the transaction. Other HTTP and malformed-response errors fail.
    /// One absolute monotonic deadline bounds every status dispatch, polling sleep and
    /// outcome admission, shortened by any earlier context request deadline. Explicit
    /// zero timeout fails unresolved without a read; use the one-shot status API for
    /// one observation. A late response cannot confirm finality or undo a committed
    /// transaction. Custom blocking transports must honor the supplied request timeout.
    ///
    /// # Errors
    /// Returns an error if polling fails, the response is not bound to the requested canonical
    /// hash/global scope, the transaction is rejected or expires, or the timeout elapses before
    /// state-resolved `Applied` is observed.
    pub fn wait_for_transaction_applied(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
    ) -> Result<TransactionWaitOutcome> {
        self.wait_for_transaction_applied_scoped(hash, options, transaction_wait::Scope::Global)
    }

    /// Wait for this configured peer to report the exact transaction as state-resolved `Applied`.
    ///
    /// Every request explicitly uses local scope; no fanout or submission occurs. Cached
    /// observations remain pending. One absolute deadline includes transport, decoding and
    /// backpressure waits. A local rejection or expiry fails this peer observation without
    /// creating an authoritative global [`TransactionFinalityFailure`].
    ///
    /// # Errors
    /// Returns binding, transport, malformed status, local terminal observation or deadline errors.
    pub fn wait_for_transaction_applied_local(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
    ) -> Result<TransactionWaitOutcome> {
        self.wait_for_transaction_applied_scoped(hash, options, transaction_wait::Scope::Local)
    }

    fn wait_for_transaction_applied_scoped(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
        scope: transaction_wait::Scope,
    ) -> Result<TransactionWaitOutcome> {
        crate::blocking::reject_inside_async_runtime()?;
        let mut wait =
            transaction_wait::PollState::new(hash, options, self.http_transport.deadline(), scope)?;
        let polling_client = self.with_request_deadline(wait.deadline());
        loop {
            wait.begin_poll()?;
            if let Some(outcome) = wait.observe(
                polling_client
                    .get_transaction_status_response_with_scope(hash, Some(scope.as_str())),
            )? {
                return Ok(outcome);
            }
            std::thread::sleep(wait.next_delay()?);
        }
    }

    pub(crate) async fn wait_until_transaction_applied(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
    ) -> Result<TransactionWaitOutcome> {
        self.wait_until_transaction_applied_scoped(hash, options, transaction_wait::Scope::Global)
            .await
    }

    /// Asynchronously wait for the exact configured peer's state-resolved `Applied` observation.
    ///
    /// Uses the same explicit local scope, absolute deadline and failure boundary as
    /// [`Self::wait_for_transaction_applied_local`]. Never submits or falls back to fanout.
    ///
    /// # Errors
    /// Returns binding, transport, malformed status, local terminal observation or deadline errors.
    pub async fn wait_until_transaction_applied_local(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
    ) -> Result<TransactionWaitOutcome> {
        self.wait_until_transaction_applied_scoped(hash, options, transaction_wait::Scope::Local)
            .await
    }

    async fn wait_until_transaction_applied_scoped(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
        scope: transaction_wait::Scope,
    ) -> Result<TransactionWaitOutcome> {
        let mut wait =
            transaction_wait::PollState::new(hash, options, self.http_transport.deadline(), scope)?;
        let polling_client = self.with_request_deadline(wait.deadline());
        loop {
            wait.begin_poll()?;
            if let Some(outcome) = wait.observe(
                polling_client
                    .fetch_transaction_status_response_with_scope(hash, Some(scope.as_str()))
                    .await,
            )? {
                return Ok(outcome);
            }
            tokio::time::sleep(wait.next_delay()?).await;
        }
    }
    fn transaction_headers_without_content_type(&self) -> HashMap<String, String> {
        let mut headers = self.headers.clone();
        headers.retain(|name, _| !name.eq_ignore_ascii_case("content-type"));
        headers
    }
    fn prepare_transaction_payload_request(
        &self,
        payload: &PreparedTransactionPayload,
    ) -> DefaultRequestBuilder {
        // Public Torii ingress accepts a versioned SignedTransaction; internal
        // TransactionEntrypoint wrapping happens on the server boundary.
        let mut request = DefaultRequestBuilder::new(
            HttpMethod::POST,
            join_torii_url(&self.torii_url, torii_routes::pipeline::TRANSACTION.path()),
        )
        .with_transport(self.http_transport.clone())
        .headers(self.transaction_headers_without_content_type())
        .header("Content-Type", APPLICATION_NORITO)
        .header("Accept", self.wire_format_preference.accept_header())
        .body(payload.as_bytes().to_vec())
        .max_response_bytes(TRANSACTION_SUBMISSION_RESPONSE_MAX_BYTES);
        if self.torii_request_timeout != Duration::ZERO {
            request = request.timeout(self.torii_request_timeout);
        }
        request
    }
    /// Constructs an account-authenticated Events API handler for the exact WebSocket upgrade.
    /// With it, you can use any WS client you want.
    ///
    /// # Errors
    /// Fails if canonical account signing or handler construction fails.
    #[inline]
    fn events_handler(
        &self,
        event_filters: impl IntoIterator<Item = impl Into<EventFilterBox>>,
    ) -> crate::Result<events_api::flow::Init> {
        let operation = streams::EVENTS_OPERATION;
        let filters: Vec<_> = event_filters.into_iter().map(Into::into).collect();
        if filters.is_empty() {
            return Err(crate::Error::InvalidRequest {
                operation,
                details: "event WebSocket requires at least one filter".to_owned(),
            });
        }
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::streaming::SUBSCRIPTION_WS.path(),
        );
        let headers = self
            .account_signed_headers(&HttpMethod::GET, &url, &[])
            .map_err(|error| crate::Error::RequestSigning {
                operation,
                details: error.to_string(),
            })?;
        events_api::flow::Init::new(filters, headers, url).map_err(|error| {
            crate::Error::InvalidRequest {
                operation,
                details: error.to_string(),
            }
        })
    }
    /// Construct a handler for the global-reader-only Blocks API.
