    /// Query effective account permissions with the shared collection language, retaining headers.
    ///
    /// This signed raw response is intended for policy convergence callers that must require
    /// the `x-iroha-account-permission-semantics: effective-v1` header before accepting a
    /// `collections::Page<Permission>`. Follow `next_cursor` until it is absent.
    ///
    /// # Errors
    /// Returns an error when the query is invalid, signing fails, or the HTTP call fails.
    pub fn query_account_permissions_response(
        &self,
        account_id: &AccountId,
        query: &crate::collections::ListQuery,
    ) -> Result<Response<Vec<u8>>> {
        let collection = crate::collections::Collection::AccountPermissions(account_id.clone());
        collection.validate_query(query)?;
        let url = collection.query_url(&self.torii_url, self.account_chain_discriminant)?;
        let body = norito::json::to_vec(&query.to_json_value())?;
        self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Accept", APPLICATION_JSON)
                .header("Content-Type", APPLICATION_JSON)
                .max_response_bytes(4 * 1024 * 1024),
        )
    }
    /// Read the complete effective permission set for an authorization decision.
    ///
    /// Every page must advertise `effective-v1` semantics. Traversal is bounded to
    /// 32 pages and 16,000 tokens, and follows only the server's opaque cursor.
    ///
    /// # Errors
    /// Rejects failed or malformed pages, ambiguous semantics, stalled cursor traversal,
    /// or a permission set exceeding the fixed authorization-read bounds.
    pub fn read_effective_permissions(
        &self,
        account_id: &AccountId,
    ) -> Result<std::collections::BTreeSet<iroha_data_model::permission::Permission>> {
        use crate::collections::{ListQuery, Page};
        use iroha_data_model::permission::Permission;
        use std::collections::BTreeSet;
        let mut query = ListQuery::new().limit(500);
        let mut permissions = BTreeSet::new();
        let mut cursors = BTreeSet::new();
        for _ in 0..32 {
            let response = self.query_account_permissions_response(account_id, &query)?;
            if response.status() != StatusCode::OK {
                return Err(eyre!(
                    "effective permission read failed with HTTP {}",
                    response.status()
                ));
            }
            let header = |name: &str| -> Result<&str> {
                let mut values = response.headers().get_all(name).iter();
                let value = values
                    .next()
                    .ok_or_else(|| eyre!("effective permission response has no {name}"))?;
                if values.next().is_some() {
                    return Err(eyre!("effective permission response has duplicate {name}"));
                }
                value.to_str().map_err(Into::into)
            };
            if !header("content-type")?
                .split(';')
                .next()
                .unwrap_or_default()
                .trim()
                .eq_ignore_ascii_case(APPLICATION_JSON)
                || header("x-iroha-account-permission-semantics")? != "effective-v1"
            {
                return Err(eyre!(
                    "effective permission response must advertise JSON effective-v1 semantics"
                ));
            }
            if response.body().len() > 4 * 1024 * 1024 {
                return Err(eyre!(
                    "effective permission page exceeds fixed response bound"
                ));
            }
            let page: Page<Permission> = norito::json::from_slice(response.body())?;
            if page.items.len() > 500 || (page.has_more() && page.items.is_empty()) {
                return Err(eyre!(
                    "effective permission page exceeds its requested bound or makes no progress"
                ));
            }
            permissions.extend(page.items);
            if permissions.len() > 16_000 {
                return Err(eyre!("effective permissions exceed fixed collection bound"));
            }
            match page.next_cursor {
                None => return Ok(permissions),
                Some(cursor) if cursors.insert(cursor.clone()) => query.cursor = Some(cursor),
                Some(_) => return Err(eyre!("effective permission cursor did not advance")),
            }
        }
        Err(eyre!(
            "effective permissions did not reach exhaustion within the fixed traversal bound"
        ))
    }
    /// Account-signed POST `/v1/fee-sponsor-programs/by-id` retaining the exact response.
    ///
    /// # Errors
    /// Returns an error if request signing, JSON serialization, construction, or the HTTP call
    /// fails, or if the response exceeds the first-release size bound.
    pub fn post_fee_sponsor_program_by_id(
        &self,
        program_id: &FeeSponsorProgramId,
    ) -> Result<Response<Vec<u8>>> {
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::fees::SPONSOR_PROGRAM_BY_ID_PATH.trim_start_matches('/'),
        );
        let body = norito::json::to_vec(&FeeSponsorProgramByIdRequest::new(program_id))?;
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(FEE_SPONSOR_PROGRAM_RESPONSE_MAX_BYTES),
        )?;
        if response.body().len() > FEE_SPONSOR_PROGRAM_RESPONSE_MAX_BYTES {
            return Err(eyre!(
                "fee sponsor program response exceeds the {} byte limit",
                FEE_SPONSOR_PROGRAM_RESPONSE_MAX_BYTES
            ));
        }
        Ok(response)
    }
    /// Fetch one exact on-chain sponsor-program lifecycle record.
    ///
    /// A `404` is returned as `Ok(None)`. A successful response must use the
    /// JSON media type, decode as the closed first-release record, and contain
    /// the exact requested controller identity and program name.
    ///
    /// # Errors
    /// Returns an error if request signing, transport, response bounds, media
    /// type, decoding, or response-selector validation fails.
    pub fn find_fee_sponsor_program_by_id(
        &self,
        program_id: &FeeSponsorProgramId,
    ) -> Result<Option<FeeSponsorProgram>> {
        let response = self.post_fee_sponsor_program_by_id(program_id)?;
        match response.status() {
            StatusCode::NOT_FOUND => Ok(None),
            StatusCode::OK => {
                let content_type = exact_single_response_header_bytes(&response, "content-type")
                    .wrap_err("fee sponsor program response has ambiguous content-type")?;
                if !Self::is_exact_json_content_type_bytes(content_type) {
                    return Err(eyre!(
                        "fee sponsor program response has invalid content-type (expected {APPLICATION_JSON})"
                    ));
                }
                reject_explicit_null_fee_sponsor_program_optionals(response.body())?;
                let program: FeeSponsorProgram = norito::json::from_slice(response.body())
                    .wrap_err("failed to decode typed fee sponsor program response")?;
                if &program.id != program_id {
                    return Err(eyre!(
                        "fee sponsor program response id differs from the requested program"
                    ));
                }
                if program.active_revision == Some(0)
                    || program.staged_revision == Some(0)
                    || program
                        .scheduled_activation
                        .as_ref()
                        .is_some_and(|activation| {
                            activation.revision == 0 || activation.activate_at_height == 0
                        })
                {
                    return Err(eyre!(
                        "fee sponsor program response contains a zero revision or activation height"
                    ));
                }
                Ok(Some(program))
            }
            _ => Err(
                ResponseReport::with_msg("failed to fetch fee sponsor program", &response)
                    .unwrap_or_else(core::convert::identity)
                    .into(),
            ),
        }
    }
    fn fee_quote_retry_delay(response: &Response<Vec<u8>>) -> Result<Option<Duration>> {
        if response.status() != StatusCode::TOO_MANY_REQUESTS
            || response.body().len() > FEE_QUOTE_RESPONSE_MAX_BYTES
        {
            return Ok(None);
        }
        let content_type = exact_single_response_header_bytes(response, "content-type")?;
        if !Self::is_exact_json_content_type_bytes(content_type) {
            return Ok(None);
        }
        let Ok(envelope) = norito::json::from_slice::<ErrorEnvelope>(response.body()) else {
            return Ok(None);
        };
        if envelope.code() != "query_validation_failed" {
            return Ok(None);
        }
        let Some(delay) = transaction_wait::retry_after_delay(response)? else {
            return Ok(None);
        };
        if delay.is_zero() {
            return Err(eyre!("fee quote Retry-After must be positive"));
        }
        if envelope
            .details
            .as_ref()
            .and_then(|details| details.retry_after_seconds)
            != Some(delay.as_secs())
        {
            return Err(eyre!("fee quote Retry-After differs from error details"));
        }
        Ok(Some(delay))
    }

    fn decode_fee_quote_response(
        payload: &TransactionPayload,
        response: &Response<Vec<u8>>,
    ) -> Result<FeeQuoteResponse> {
        if response.body().len() > FEE_QUOTE_RESPONSE_MAX_BYTES {
            return Err(eyre!(
                "fee quote response exceeds the {} byte limit",
                FEE_QUOTE_RESPONSE_MAX_BYTES
            ));
        }
        if response.status() != StatusCode::OK {
            return Err(
                ResponseReport::with_msg("failed to quote transaction fees", response)
                    .unwrap_or_else(core::convert::identity)
                    .into(),
            );
        }
        let content_type = exact_single_response_header_bytes(response, "content-type")
            .wrap_err("fee quote response has ambiguous content-type")?;
        if !Self::is_exact_json_content_type_bytes(content_type) {
            return Err(eyre!(
                "fee quote response has invalid content-type (expected {APPLICATION_JSON})"
            ));
        }
        let quote: FeeQuoteResponse = norito::json::from_slice(response.body())
            .wrap_err("failed to decode typed fee quote response")?;
        quote
            .validate_for_draft(payload)
            .map_err(|error| eyre!(error))
            .wrap_err("fee quote response does not match the requested transaction payload")?;
        Ok(quote)
    }
