    /// Convenience: account-signed, selector-explicit POST `/v1/multisig/spec`.
    ///
    /// # Errors
    /// Returns an error if request signing, construction, JSON serialization, the HTTP call,
    /// or closed-schema response decoding fails.
    pub fn post_multisig_spec(
        &self,
        request: &MultisigSpecRequest,
    ) -> Result<MultisigSpecResponse> {
        validate_multisig_read_selector(
            request.multisig_account_id.as_ref(),
            request.multisig_account_alias.as_deref(),
        )?;
        let url = join_torii_url(&self.torii_url, "v1/multisig/spec");
        let body = norito::json::to_vec(request)?;
        let resp = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON),
        )?;
        Self::ensure_response_status(
            &resp,
            StatusCode::OK,
            "Failed to read multisig spec with HTTP status",
            ". ",
        )?;
        let decoded: MultisigSpecResponse = norito::json::from_slice(resp.body())
            .map_err(|err| eyre!("failed to decode closed multisig spec response: {err}"))?;
        if request
            .multisig_account_id
            .as_ref()
            .is_some_and(|expected| expected != &decoded.resolved_multisig_account_id)
        {
            return Err(eyre!(
                "multisig spec response resolved account does not match the requested account"
            ));
        }
        Ok(decoded)
    }
    /// Convenience: account-signed, selector-explicit POST `/v1/multisig/proposals/query`.
    ///
    /// # Errors
    /// Returns an error if request construction, JSON serialization, the HTTP call,
    /// or response decoding fails.
    pub fn post_multisig_proposals_query(
        &self,
        request: &MultisigProposalsQueryRequest,
    ) -> Result<MultisigProposalsQueryResponse> {
        validate_multisig_read_selector(
            request.multisig_account_id.as_ref(),
            request.multisig_account_alias.as_deref(),
        )?;
        let url = join_torii_url(&self.torii_url, "v1/multisig/proposals/query");
        let body = norito::json::to_vec(request)?;
        let resp = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON),
        )?;
        Self::ensure_response_status(
            &resp,
            StatusCode::OK,
            "Failed to query multisig proposals with HTTP status",
            ". ",
        )?;
        let decoded: MultisigProposalsQueryResponse = norito::json::from_slice(resp.body())
            .map_err(|err| {
                eyre!("failed to decode closed multisig proposals query response: {err}")
            })?;
        if request
            .multisig_account_id
            .as_ref()
            .is_some_and(|expected| expected != &decoded.resolved_multisig_account_id)
        {
            return Err(eyre!(
                "multisig proposals query response resolved account does not match the requested account"
            ));
        }
        let mut occurrences = std::collections::BTreeSet::new();
        for entry in &decoded.proposals {
            validate_multisig_proposal_binding(
                &self.network_id,
                &decoded.resolved_multisig_account_id,
                &entry.proposal_id,
                &entry.instructions_hash,
                &entry.proposal,
            )?;
            if !occurrences.insert(&entry.proposal_id) {
                return Err(eyre!("multisig proposal page repeats an occurrence"));
            }
        }
        Ok(decoded)
    }
    /// Convenience: selector-explicit POST `/v1/multisig/proposals/resolve`.
    ///
    /// # Errors
    /// Returns an error if the authority or proposal selector is not exact, request
    /// construction or JSON serialization fails, the HTTP call fails, or the response
    /// cannot be decoded.
    pub fn post_multisig_proposals_resolve(
        &self,
        request: &MultisigProposalsResolveRequest,
    ) -> Result<MultisigProposalResolveResponse> {
        validate_multisig_read_selector(
            request.multisig_account_id.as_ref(),
            request.multisig_account_alias.as_deref(),
        )?;
        validate_multisig_proposal_read_selector(&request.proposal_id)?;
        let url = join_torii_url(&self.torii_url, "v1/multisig/proposals/resolve");
        let body = norito::json::to_vec(request)?;
        let resp = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON),
        )?;
        Self::ensure_response_status(
            &resp,
            StatusCode::OK,
            "Failed to resolve multisig proposal with HTTP status",
            ". ",
        )?;
        let decoded: MultisigProposalResolveResponse = norito::json::from_slice(resp.body())
            .map_err(|err| {
                eyre!("failed to decode closed multisig proposal resolve response: {err}")
            })?;
        if request
            .multisig_account_id
            .as_ref()
            .is_some_and(|expected| expected != &decoded.resolved_multisig_account_id)
        {
            return Err(eyre!(
                "multisig proposal resolve response resolved account does not match the requested account"
            ));
        }
        if request.proposal_id != decoded.proposal_id {
            return Err(eyre!(
                "multisig proposal resolve response selected another occurrence"
            ));
        }
        validate_multisig_proposal_binding(
            &self.network_id,
            &decoded.resolved_multisig_account_id,
            &decoded.proposal_id,
            &decoded.instructions_hash,
            &decoded.proposal,
        )?;
        Ok(decoded)
    }
    /// Convenience: POST `/v1/multisig/propose` with a typed instruction batch.
    ///
    /// `InstructionBox` values are encoded in JSON as base64 native Norito frames,
    /// which lets callers avoid manually shaping JSON instruction objects.
    /// The caller must independently resolve and select the concrete multisig account;
    /// a response-provided alias resolution cannot authorize its own signing payload.
    ///
    /// # Errors
    /// Returns an error if request construction, JSON serialization, the HTTP call,
    /// or response decoding fails.
    pub fn post_multisig_propose(
        &self,
        request: &MultisigProposeRequest,
    ) -> Result<MultisigResponse> {
        let body =
            norito::json::to_vec(request).wrap_err("failed to encode multisig propose request")?;
        let url = join_torii_url(&self.torii_url, "v1/multisig/propose");
        let response = self
            .default_request(HttpMethod::POST, url)
            .header("Content-Type", APPLICATION_JSON)
            .header("Accept", APPLICATION_JSON)
            .body(body)
            .build()?
            .send_blocking()?;
        if response.status() != StatusCode::OK {
            return Err(ResponseReport::with_msg(
                "failed to propose multisig instruction batch",
                &response,
            )
            .unwrap_or_else(core::convert::identity)
            .into());
        }
        let decoded = norito::json::from_slice(response.body())
            .map_err(|err| eyre!("failed to decode multisig propose response: {err}"))?;
        multisig_validation::validate_response(&decoded, request, self.network_id)
            .wrap_err("failed to validate multisig propose response")?;
        Ok(decoded)
    }
    /// Convenience: GET `/v1/sorafs/pin` to list manifests in the pin registry.
    /// # Errors
    /// Returns an error for a noncanonical manifest-digest cursor, request construction, or an
    /// HTTP failure.
    pub fn get_sorafs_pin_registry(
        &self,
        filter: &SorafsPinListFilter<'_>,
    ) -> Result<Response<Vec<u8>>> {
        let endpoint = SorafsEndpoint::anonymous_json_get("v1/sorafs/pin");
        let mut url = join_torii_url(&self.torii_url, endpoint.path);
        filter.apply_to_url(&mut url)?;
        self.send_sorafs_url(endpoint, url, Vec::new())
    }
    /// Convenience: GET `/v1/sorafs/pin/{digest}` to inspect a specific manifest record.
    /// # Errors
    /// Returns an error if `digest_hex` is not an exact non-zero lowercase 32-byte digest, or if
    /// request construction or the HTTP call fails.
    pub fn get_sorafs_pin_manifest(&self, digest_hex: &str) -> Result<Response<Vec<u8>>> {
        let digest_hex = require_nonzero_lower_hex32(digest_hex, "SoraFS pin manifest digest")?;
        let path = format!("v1/sorafs/pin/{digest_hex}");
        let url = join_torii_url(&self.torii_url, &path);
        let response = self
            .default_request(HttpMethod::GET, url)
            .header("Accept", APPLICATION_JSON)
            .build()?
            .send_blocking()?;
        self.enforce_alias_policy(&response)?;
        Ok(response)
    }
    /// Build a signed DA ingest request using the client's key pair.
    ///
    /// This mirrors `iroha da submit --no-submit`, returning the Norito payload so callers can
    /// persist it to disk or inspect the JSON before publishing.
    ///
    /// # Errors
    ///
    /// Returns an error if signing the DA ingest payload fails.
    pub fn build_da_ingest_request(
        &self,
        payload: impl Into<Vec<u8>>,
        params: &DaIngestParams,
        metadata: ExtraMetadata,
        manifest_bytes: Option<Vec<u8>>,
    ) -> Result<DaIngestRequest> {
        build_da_request(
            self.network_id,
            self.account.clone(),
            payload.into(),
            params,
            metadata,
            &self.key_pair,
            manifest_bytes,
        )
    }
    /// Add the client's signature over an exact pin scope returned for a prepared request.
    ///
    /// The original request is left unchanged. The returned clone retains the original
    /// request authorization and adds the post-ingest scope witness needed to finalize it.
    ///
    /// # Errors
    ///
    /// Returns an error if the scope does not match the prepared request, signing fails, or
    /// the client's key is already present among the scope witnesses.
    pub fn authorize_da_pin_scope(
        &self,
        request: &DaIngestRequest,
        scope: &DaPinScopeV1,
    ) -> Result<DaIngestRequest> {
        let mut authorized_request = request.clone();
        authorized_request
            .try_add_pin_scope_signature(scope, &self.key_pair)
            .wrap_err("failed to authorize DA pin scope")?;
        Ok(authorized_request)
    }
    /// Authorize an exact pin scope and retry the prepared DA ingest request once.
    ///
    /// This method performs one HTTP submission and returns its response even when Torii still
    /// reports `pending_pin_authorization`; callers can gather additional controller witnesses
    /// explicitly without entering an unbounded retry loop.
    ///
    /// # Errors
    ///
    /// Returns an error if the scope does not match the request, signing fails, the HTTP
    /// submission is rejected, or Torii substitutes the scoped response or receipt.
    pub fn authorize_and_retry_da_ingest(
        &self,
        request: &DaIngestRequest,
        scope: &DaPinScopeV1,
    ) -> Result<DaIngestSubmitResult> {
        self.authorize_and_retry_da_ingest_with_request(request, scope)
            .map(|(result, _)| result)
    }
    /// Submit a DA blob to `/v1/da/ingest` and return the Torii receipt.
    ///
    /// This is equivalent to running `iroha da submit` with the provided parameters.
    ///
    /// # Errors
    ///
    /// Returns an error if building the request fails or the HTTP submission is rejected.
    pub fn submit_da_blob(
        &self,
        payload: impl Into<Vec<u8>>,
        params: &DaIngestParams,
        metadata: ExtraMetadata,
        manifest_bytes: Option<Vec<u8>>,
    ) -> Result<DaIngestSubmitResult> {
        let request = self.build_da_ingest_request(payload, params, metadata, manifest_bytes)?;
        self.submit_prepared_da_request(&request)
    }
    /// Build and persist a DA ingest request without submitting it to Torii.
    ///
    /// This mirrors `iroha da submit --no-submit`, writing `da_request.{norito,json}` into
    /// `output_dir` so callers can inspect or publish the request later.
    ///
    /// # Errors
    ///
    /// Returns an error if request signing fails or the request artefacts cannot
    /// be encoded or written to disk.
    pub fn write_da_ingest_request(
        &self,
        payload: impl Into<Vec<u8>>,
        params: &DaIngestParams,
        metadata: ExtraMetadata,
        manifest_bytes: Option<Vec<u8>>,
        output_dir: impl AsRef<Path>,
    ) -> Result<DaIngestPersistedPaths> {
        let request = self.build_da_ingest_request(payload, params, metadata, manifest_bytes)?;
        Self::persist_da_ingest_artifacts(&request, None, None, output_dir)
    }
    /// Submit a DA ingest request and persist the CLI-compatible artefacts.
    ///
    /// Writes `da_request.{norito,json}` and, when present, `da_receipt.{norito,json}` plus
    /// `da_response_headers.json` into `output_dir`, mirroring `iroha da submit`.
    ///
    /// # Errors
    ///
    /// Returns an error if request signing fails, the HTTP submission fails, or
    /// any artefact cannot be written to disk.
    pub fn submit_da_blob_to_dir(
        &self,
        payload: impl Into<Vec<u8>>,
        params: &DaIngestParams,
        metadata: ExtraMetadata,
        manifest_bytes: Option<Vec<u8>>,
        output_dir: impl AsRef<Path>,
    ) -> Result<(DaIngestSubmitResult, DaIngestPersistedPaths)> {
        let request = self.build_da_ingest_request(payload, params, metadata, manifest_bytes)?;
        // Persist the request up front so the caller retains the Norito bytes even if submit fails.
        Self::persist_da_ingest_artifacts(&request, None, None, &output_dir)?;
        let (result, authorized_request) = self.submit_prepared_da_request_with_retry(&request)?;
        let persisted_request = authorized_request.as_ref().unwrap_or(&request);
        let persisted = Self::persist_da_ingest_artifacts(
            persisted_request,
            result.receipt.as_ref(),
            result.pdp_commitment.as_ref(),
            output_dir,
        )?;
        Ok((result, persisted))
    }
    fn submit_prepared_da_request(
        &self,
        request: &DaIngestRequest,
    ) -> Result<DaIngestSubmitResult> {
        self.submit_prepared_da_request_with_retry(request)
            .map(|(result, _)| result)
    }
    fn submit_prepared_da_request_with_retry(
        &self,
        request: &DaIngestRequest,
    ) -> Result<(DaIngestSubmitResult, Option<DaIngestRequest>)> {
        let prepared_result = self.submit_prepared_da_request_once(request)?;
        if prepared_result.status == "accepted" {
            let scope = prepared_result.pin_scope.as_ref().ok_or_else(|| {
                eyre!("Torii returned `accepted` without the durable DA pin scope")
            })?;
            Self::validate_da_ingest_scoped_response(request, scope, &prepared_result)?;
            return Ok((prepared_result, None));
        }
        if prepared_result.status != "pending_pin_authorization" {
            return Err(eyre!(
                "Torii returned unexpected DA ingest status `{}`",
                prepared_result.status
            ));
        }
        let scope = prepared_result.pin_scope.as_ref().ok_or_else(|| {
            eyre!("Torii returned `pending_pin_authorization` without a DA pin scope")
        })?;
        Self::validate_da_ingest_scoped_response(request, scope, &prepared_result)?;
        let (finalized_result, authorized_request) =
            self.authorize_and_retry_da_ingest_with_request(request, scope)?;
        if finalized_result.status != "accepted"
            && finalized_result.status != "pending_pin_authorization"
        {
            return Err(eyre!(
                "Torii returned unexpected DA ingest status `{}` after pin authorization",
                finalized_result.status
            ));
        }
        if finalized_result.pin_scope != prepared_result.pin_scope
            || finalized_result.receipt != prepared_result.receipt
            || finalized_result.pdp_commitment != prepared_result.pdp_commitment
        {
            return Err(eyre!(
                "Torii changed the durable DA receipt, pin scope, or PDP commitment during pin authorization"
            ));
        }
        Ok((finalized_result, Some(authorized_request)))
    }
    fn authorize_and_retry_da_ingest_with_request(
        &self,
        request: &DaIngestRequest,
        scope: &DaPinScopeV1,
    ) -> Result<(DaIngestSubmitResult, DaIngestRequest)> {
        let authorized_request = self.authorize_da_pin_scope(request, scope)?;
        let result = self.submit_prepared_da_request_once(&authorized_request)?;
        Self::validate_da_ingest_scoped_response(request, scope, &result)?;
        Ok((result, authorized_request))
    }
    fn validate_da_ingest_scoped_response(
        request: &DaIngestRequest,
        expected_scope: &DaPinScopeV1,
        result: &DaIngestSubmitResult,
    ) -> Result<()> {
        if result.status != "accepted" && result.status != "pending_pin_authorization" {
            return Err(eyre!(
                "Torii returned unexpected DA ingest status `{}` for a scoped response",
                result.status
            ));
        }
        if !expected_scope.matches_authorization(&request.authorization()) {
            return Err(eyre!(
                "Torii DA pin scope does not match the submitted request authorization"
            ));
        }
        if result.pin_scope.as_ref() != Some(expected_scope) {
            return Err(eyre!(
                "Torii changed the exact DA pin scope during pin authorization"
            ));
        }
        let receipt = result
            .receipt
            .as_ref()
            .ok_or_else(|| eyre!("Torii scoped DA ingest response is missing its receipt"))?;
        let receipt_matches_request = (
            &receipt.client_blob_id,
            receipt.lane_id,
            receipt.epoch,
            &receipt.blob_hash,
        ) == (
            &request.client_blob_id,
            request.lane_id,
            request.epoch,
            &request.payload_hash,
        );
        let receipt_matches_scope = receipt.storage_ticket == expected_scope.storage_ticket
            && receipt.manifest_hash.as_bytes() == expected_scope.manifest_hash.as_bytes();
        if !receipt_matches_request || !receipt_matches_scope {
            return Err(eyre!(
                "Torii DA receipt does not match the submitted request and exact pin scope"
            ));
        }
        if result.pdp_commitment.as_ref().is_some_and(|commitment| {
            commitment.manifest_digest != *expected_scope.manifest_hash.as_bytes()
                || commitment.payload_len != request.total_size
        }) {
            return Err(eyre!(
                "Torii PDP commitment does not match the submitted request and exact pin scope"
            ));
        }
        Ok(())
    }
    fn submit_prepared_da_request_once(
        &self,
        request: &DaIngestRequest,
    ) -> Result<DaIngestSubmitResult> {
        let body =
            norito::json::to_vec(request).wrap_err("failed to encode DA ingest request JSON")?;
        let url = join_torii_url(&self.torii_url, "v1/da/ingest");
        let response = self
            .account_signed_request(HttpMethod::POST, url, body)?
            .header("Content-Type", APPLICATION_JSON)
            .header("Accept", APPLICATION_JSON)
            .build()?;
        let response = self.send_prepared_request(response)?;
        let status_code = response.status();
        if status_code != StatusCode::ACCEPTED && status_code != StatusCode::OK {
            return Err(
                ResponseReport::with_msg("failed to submit DA ingest request", &response)
                    .unwrap_or_else(core::convert::identity)
                    .into(),
            );
        }
        let (payload, receipt_json, pdp_commitment) = Self::decode_da_ingest_response(
            response.body(),
            response.headers().get(PDP_COMMITMENT_HEADER),
        )?;
        Ok(DaIngestSubmitResult {
            status: payload.status,
            duplicate: payload.duplicate,
            receipt: payload.receipt,
            pin_scope: payload.pin_scope,
            receipt_json,
            pdp_commitment,
            client_blob_id: request.client_blob_id,
            payload_len: request.payload.len(),
        })
    }
    /// Decode a JSON DA ingest response payload plus optional PDP commitment header.
    fn decode_da_ingest_response(
        response_bytes: &[u8],
        header: Option<&http::header::HeaderValue>,
    ) -> Result<(
        DaIngestResponsePayload,
        Option<String>,
        Option<PdpCommitmentV1>,
    )> {
        let payload: DaIngestResponsePayload = norito::json::from_slice(response_bytes)
            .wrap_err("failed to decode DA ingest response")?;
        let receipt_json = match payload.receipt.as_ref() {
            Some(receipt) => Some(
                norito::json::to_json_pretty(receipt)
                    .wrap_err("failed to render DA ingest receipt JSON")?,
            ),
            None => None,
        };
        let pdp_commitment = match header {
            Some(value) => {
                let raw = value
                    .to_str()
                    .wrap_err("sora-pdp-commitment header must contain ASCII")?;
                Some(decode_pdp_commitment_header(raw)?)
            }
            None => None,
        };
        Ok((payload, receipt_json, pdp_commitment))
    }
    fn persist_da_ingest_artifacts(
        request: &DaIngestRequest,
        receipt: Option<&DaIngestReceipt>,
        pdp_commitment: Option<&PdpCommitmentV1>,
        output_dir: impl AsRef<Path>,
    ) -> Result<DaIngestPersistedPaths> {
        let output_dir = output_dir.as_ref();
        if output_dir.as_os_str().is_empty() {
            return Err(eyre!("DA ingest artifact directory must not be empty"));
        }
        std::fs::create_dir_all(output_dir).wrap_err_with(|| {
            format!(
                "failed to create DA ingest artifact directory `{}`",
                output_dir.display()
            )
        })?;
        let request_raw = output_dir.join("da_request.norito");
        let request_json = output_dir.join("da_request.json");
        let request_bytes =
            to_bytes(request).wrap_err("failed to encode DA ingest request as Norito")?;
        let request_json_body = norito::json::to_json_pretty(request)
            .map_err(|err| eyre!("failed to render DA ingest request JSON: {err}"))?;
        std::fs::write(&request_raw, &request_bytes)
            .wrap_err_with(|| format!("failed to write `{}`", request_raw.display()))?;
        std::fs::write(&request_json, format!("{request_json_body}\n"))
            .wrap_err_with(|| format!("failed to write `{}`", request_json.display()))?;
        let (receipt_raw, receipt_json, response_headers_json) = receipt
            .map(|receipt| -> Result<(_, _, _)> {
                let raw_path = output_dir.join("da_receipt.norito");
                let json_path = output_dir.join("da_receipt.json");
                let receipt_bytes =
                    to_bytes(receipt).wrap_err("failed to encode DA receipt as Norito")?;
                let receipt_json_body = norito::json::to_json_pretty(receipt)
                    .map_err(|err| eyre!("failed to render DA receipt JSON: {err}"))?;
                std::fs::write(&raw_path, &receipt_bytes)
                    .wrap_err_with(|| format!("failed to write `{}`", raw_path.display()))?;
                std::fs::write(&json_path, format!("{receipt_json_body}\n"))
                    .wrap_err_with(|| format!("failed to write `{}`", json_path.display()))?;
                let headers_path = pdp_commitment
                    .map(|commitment| -> Result<_> {
                        let mut headers = JsonMap::new();
                        let encoded = to_bytes(commitment)
                            .wrap_err("failed to encode PDP commitment for header JSON")?;
                        headers.insert(
                            PDP_COMMITMENT_HEADER.into(),
                            JsonValue::from(
                                base64::engine::general_purpose::STANDARD.encode(encoded),
                            ),
                        );
                        let rendered = norito::json::to_json_pretty(&JsonValue::Object(headers))
                            .map_err(|err| {
                                eyre!("failed to render DA response header JSON: {err}")
                            })?;
                        let path = output_dir.join("da_response_headers.json");
                        std::fs::write(&path, format!("{rendered}\n"))
                            .wrap_err_with(|| format!("failed to write `{}`", path.display()))?;
                        Ok(path)
                    })
                    .transpose()?;
                Ok((Some(raw_path), Some(json_path), headers_path))
            })
            .transpose()?
            .unwrap_or((None, None, None));
        Ok(DaIngestPersistedPaths {
            request_raw,
            request_json,
            receipt_raw,
            receipt_json,
            response_headers_json,
        })
    }
    fn validate_sorafs_pin_alias_segment(value: &str, field: &str) -> Result<()> {
        let bytes = value.as_bytes();
        if bytes.is_empty()
            || bytes.len() > SORAFS_PIN_REGISTER_MAX_ALIAS_SEGMENT_BYTES
            || !bytes.iter().all(|byte| {
                byte.is_ascii_lowercase()
                    || byte.is_ascii_digit()
                    || matches!(*byte, b'.' | b'-' | b'_')
            })
        {
            return Err(eyre!(
                "{field} must contain 1..={SORAFS_PIN_REGISTER_MAX_ALIAS_SEGMENT_BYTES} \
                 lowercase ASCII letters, digits, '.', '-', or '_'"
            ));
        }
        Ok(())
    }
    fn sorafs_pin_alias_binding(
        alias: SorafsPinAlias<'_>,
    ) -> Result<iroha_data_model::sorafs::pin_registry::ManifestAliasBinding> {
        Self::validate_sorafs_pin_alias_segment(alias.namespace, "alias.namespace")?;
        Self::validate_sorafs_pin_alias_segment(alias.name, "alias.name")?;
        if alias.proof.is_empty() || alias.proof.len() > SORAFS_PIN_REGISTER_MAX_ALIAS_PROOF_BYTES {
            return Err(eyre!(
                "alias.proof must contain 1..={SORAFS_PIN_REGISTER_MAX_ALIAS_PROOF_BYTES} bytes"
            ));
        }
        Ok(
            iroha_data_model::sorafs::pin_registry::ManifestAliasBinding {
                namespace: alias.namespace.to_owned(),
                name: alias.name.to_owned(),
                proof: alias.proof.to_vec(),
            },
        )
    }
    fn validate_sorafs_pin_register_manifest_payload(manifest_payload: &[u8]) -> Result<()> {
        if manifest_payload.is_empty()
            || manifest_payload.len() > sorafs_manifest::MAX_MANIFEST_ENCODED_BYTES
        {
            return Err(eyre!(
                "manifest_payload must contain 1..={} bytes",
                sorafs_manifest::MAX_MANIFEST_ENCODED_BYTES
            ));
        }
        sorafs_manifest::decode_manifest_v1_canonical(manifest_payload)
            .wrap_err("failed to decode canonical manifest_payload for pin registration")?;
        Ok(())
    }
    fn build_sorafs_pin_register_instruction(
        params: SorafsPinRegisterArgs<'_>,
    ) -> Result<iroha_data_model::isi::sorafs::RegisterPinManifest> {
        let SorafsPinRegisterArgs {
            manifest_payload,
            alias,
            successor_of,
        } = params;
        Self::validate_sorafs_pin_register_manifest_payload(manifest_payload)?;
        let alias = alias.map(Self::sorafs_pin_alias_binding).transpose()?;
        let successor_of = successor_of
            .map(|successor| {
                if successor == [0; 32] {
                    return Err(eyre!("successor_of must not be the all-zero digest"));
                }
                Ok(iroha_data_model::sorafs::pin_registry::ManifestDigest::new(
                    successor,
                ))
            })
            .transpose()?;
        Ok(iroha_data_model::isi::sorafs::RegisterPinManifest::new(
            manifest_payload.to_vec(),
            alias,
            successor_of,
        ))
    }
