    fn sorafs_required_text(value: &str, field: &str) -> Result<String> {
        let trimmed = value.trim();
        if trimmed.is_empty() {
            return Err(eyre!("{field} must not be empty"));
        }
        Ok(trimmed.to_owned())
    }
    fn sorafs_optional_text(value: Option<&str>, field: &str) -> Result<Option<String>> {
        value
            .map(|text| Self::sorafs_required_text(text, field))
            .transpose()
    }
    fn sorafs_json_object<const N: usize>(fields: [(&str, JsonValue); N]) -> Result<Vec<u8>> {
        let map: JsonMap = fields
            .into_iter()
            .map(|(key, value)| (key.to_owned(), value))
            .collect();
        Ok(norito::json::to_vec(&JsonValue::Object(map))?)
    }
    fn sorafs_moderation_model_registry_manifest_body(manifest_bytes: &[u8]) -> Result<Vec<u8>> {
        if manifest_bytes.is_empty() {
            return Err(eyre!("manifest_bytes must not be empty"));
        }
        Self::sorafs_json_object([(
            "manifest_b64",
            JsonValue::from(base64::engine::general_purpose::STANDARD.encode(manifest_bytes)),
        )])
    }
    fn sorafs_json_request_body(payload: &[u8], context: &str) -> Result<Vec<u8>> {
        if payload.is_empty() {
            return Err(eyre!("{context} payload must not be empty"));
        }
        let value: JsonValue = norito::json::from_slice(payload)
            .wrap_err_with(|| format!("failed to decode {context} JSON"))?;
        Ok(norito::json::to_vec(&value)?)
    }
    fn post_sorafs_signed_json(
        &self,
        path: &str,
        payload: &[u8],
        context: &str,
    ) -> Result<Response<Vec<u8>>> {
        let payload = Self::sorafs_json_request_body(payload, context)?;
        self.send_sorafs_endpoint(SorafsEndpoint::account_json_post(path), payload, |_| {})
    }
    fn sorafs_moderation_quarantine_review_body(
        request: &SorafsModerationQuarantineReviewRequest<'_>,
    ) -> Result<Vec<u8>> {
        let reviewed_by = Self::sorafs_required_text(request.reviewed_by, "reviewed_by")?;
        let notes = Self::sorafs_optional_text(request.notes, "notes")?;
        Self::sorafs_json_object([
            ("reviewed_by", JsonValue::from(reviewed_by)),
            (
                "reviewed_at_unix",
                request
                    .reviewed_at_unix
                    .map_or(JsonValue::Null, JsonValue::from),
            ),
            ("notes", notes.map_or(JsonValue::Null, JsonValue::from)),
        ])
    }
    fn sorafs_moderation_screening_result_body(
        request: &SorafsModerationScreeningResultRequest<'_>,
    ) -> Result<Vec<u8>> {
        const AUTHORITY_MAX_BYTES: usize = 256 * 1024;
        const MEMBER_MAX_BYTES: usize = 64 * 1024;
        const COMMITTEE_MAX_RESULTS: usize = 64;
        let idempotency_key_hex =
            normalize_hex_lower::<32>(request.idempotency_key_hex, "idempotency_key_hex")?;
        if idempotency_key_hex.bytes().all(|byte| byte == b'0') {
            return Err(eyre!("idempotency_key_hex must not be all zeroes"));
        }
        let evidence_kind = Self::sorafs_required_text(request.evidence_kind, "evidence_kind")?;
        if !matches!(
            evidence_kind.as_str(),
            "signed_result" | "committee_aggregate"
        ) {
            return Err(eyre!(
                "evidence_kind must be `signed_result` or `committee_aggregate`"
            ));
        }
        validate_canonical_standard_base64(
            request.authority_b64,
            AUTHORITY_MAX_BYTES,
            "authority_b64",
        )?;
        match evidence_kind.as_str() {
            "signed_result" if !request.committee_member_results_b64.is_empty() => {
                return Err(eyre!(
                    "signed_result must not include committee_member_results_b64"
                ));
            }
            "committee_aggregate"
                if request.committee_member_results_b64.is_empty()
                    || request.committee_member_results_b64.len() > COMMITTEE_MAX_RESULTS =>
            {
                return Err(eyre!(
                    "committee_member_results_b64 must contain 1..={COMMITTEE_MAX_RESULTS} signed results"
                ));
            }
            _ => {}
        }
        let committee_member_results_b64 = request
            .committee_member_results_b64
            .iter()
            .enumerate()
            .map(|(index, encoded)| {
                validate_canonical_standard_base64(
                    encoded,
                    MEMBER_MAX_BYTES,
                    &format!("committee_member_results_b64[{index}]"),
                )?;
                Ok(JsonValue::from(encoded.clone()))
            })
            .collect::<Result<Vec<_>>>()?;
        Self::sorafs_json_object([
            ("idempotency_key_hex", JsonValue::from(idempotency_key_hex)),
            ("evidence_kind", JsonValue::from(evidence_kind)),
            ("authority_b64", JsonValue::from(request.authority_b64)),
            (
                "committee_member_results_b64",
                JsonValue::Array(committee_member_results_b64),
            ),
        ])
    }
    fn sorafs_moderation_quarantine_release_body(
        request: &SorafsModerationQuarantineReleaseRequest<'_>,
    ) -> Result<Vec<u8>> {
        let release_authority =
            Self::sorafs_required_text(request.release_authority, "release_authority")?;
        let notes = Self::sorafs_optional_text(request.notes, "notes")?;
        Self::sorafs_json_object([
            ("release_authority", JsonValue::from(release_authority)),
            (
                "released_at_unix",
                request
                    .released_at_unix
                    .map_or(JsonValue::Null, JsonValue::from),
            ),
            ("notes", notes.map_or(JsonValue::Null, JsonValue::from)),
        ])
    }
    fn sorafs_moderation_quarantine_object_store_body(
        request: &SorafsModerationQuarantineObjectStoreRequest<'_>,
    ) -> Result<Vec<u8>> {
        if request.payload.is_empty() {
            return Err(eyre!("payload must not be empty"));
        }
        let content_type = Self::sorafs_optional_text(request.content_type, "content_type")?;
        let notes = Self::sorafs_optional_text(request.notes, "notes")?;
        Self::sorafs_json_object([
            (
                "payload_b64",
                JsonValue::from(base64::engine::general_purpose::STANDARD.encode(request.payload)),
            ),
            (
                "captured_at_unix",
                request
                    .captured_at_unix
                    .map_or(JsonValue::Null, JsonValue::from),
            ),
            (
                "content_type",
                content_type.map_or(JsonValue::Null, JsonValue::from),
            ),
            ("notes", notes.map_or(JsonValue::Null, JsonValue::from)),
        ])
    }
    /// Convenience: POST `/v1/sorafs/storage/token` to mint a stream token.
    /// # Errors
    /// Returns an error if request construction or the HTTP call fails.
    pub fn post_sorafs_storage_token(
        &self,
        manifest_id_hex: &str,
        provider_id_hex: &str,
        client_id: &str,
        nonce: &str,
        overrides: &SorafsTokenOverrides,
    ) -> Result<Response<Vec<u8>>> {
        let url = join_torii_url(&self.torii_url, "v1/sorafs/storage/token");
        let mut map = norito::json::Map::new();
        map.insert(
            "manifest_id_hex".into(),
            norito::json::Value::from(manifest_id_hex),
        );
        map.insert(
            "provider_id_hex".into(),
            norito::json::Value::from(provider_id_hex),
        );
        map.insert(
            "ttl_secs".into(),
            overrides
                .ttl_secs
                .map_or(norito::json::Value::Null, norito::json::Value::from),
        );
        map.insert(
            "max_streams".into(),
            overrides
                .max_streams
                .map_or(norito::json::Value::Null, |value| {
                    norito::json::Value::from(u64::from(value))
                }),
        );
        map.insert(
            "rate_limit_bytes".into(),
            overrides
                .rate_limit_bytes
                .map_or(norito::json::Value::Null, norito::json::Value::from),
        );
        map.insert(
            "requests_per_minute".into(),
            overrides
                .requests_per_minute
                .map_or(norito::json::Value::Null, norito::json::Value::from),
        );
        let body = norito::json::to_vec(&norito::json::Value::Object(map))?;
        self.operator_signed_request(HttpMethod::POST, url, body)?
            .header("Content-Type", APPLICATION_JSON)
            .header(HEADER_SORA_CLIENT, client_id)
            .header(HEADER_SORA_NONCE, nonce)
            .build()?
            .send_blocking()
    }
