    /// Draft one canonical deploy-contract proposal instruction for local signing.
    ///
    /// The response is rejected unless the decoded instruction and typed
    /// proposal identifier bind the complete request, including manifest
    /// provenance.
    ///
    /// # Errors
    /// Returns an error for an invalid target or ABI version, transport or HTTP
    /// failure, malformed JSON, or any response-binding mismatch.
    pub fn post_deploy_contract_proposal_draft(
        &self,
        request: &DeployContractProposalDraftRequestV1,
    ) -> Result<DeployContractProposalDraftResponseV1> {
        if request.proposal_operator != self.account {
            return Err(eyre!(
                "deploy-contract proposal operator must equal the client transaction authority"
            ));
        }
        if request.abi_version.get() != 1 {
            return Err(eyre!(
                "deploy-contract proposal ABI version must be exactly one"
            ));
        }
        if matches!(
            (&request.contract_address, &request.contract_alias),
            (Some(_), Some(_)) | (None, None)
        ) {
            return Err(eyre!(
                "deploy-contract proposal must select exactly one contract address or alias"
            ));
        }
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::GOV_PROPOSE_DEPLOY.path(),
        );
        let body = norito::json::to_vec(request)
            .wrap_err("failed to encode deploy-contract proposal draft request")?;
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(GOVERNANCE_PROPOSAL_JSON_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &response,
            StatusCode::OK,
            "Failed to draft deploy-contract proposal",
            " ",
        )?;
        let content_type = Self::response_content_type(&response);
        if !Self::is_exact_json_content_type(content_type) {
            return Err(eyre!(
                "deploy-contract proposal draft response has invalid content type {content_type}"
            ));
        }
        let response: DeployContractProposalDraftResponseV1 =
            norito::json::from_slice(response.body())
                .wrap_err("failed to decode typed deploy-contract proposal draft response")?;
        validate_deploy_contract_proposal_draft_response(&response, request)?;
        Ok(response)
    }
    /// POST `/v1/gov/proposals/sccp-route-governance` with one `SccpGovernanceProposalV1`.
    ///
    /// The proposal is checked locally against the client's `NetworkId` with the same
    /// state-independent rules Torii applies (`specs/sccp.md` §4.14.3). The endpoint returns only
    /// an instruction draft. Signing material is never sent to Torii; callers inspect and sign
    /// the returned instruction locally through the normal transaction pipeline.
    ///
    /// # Errors
    ///
    /// Returns an error for a statically invalid proposal, transport or HTTP failure, a
    /// non-JSON response, or a response whose proposal id or framed instruction differs from
    /// the exact request.
    pub fn post_sccp_route_governance_draft(
        &self,
        request: &SccpRouteGovernanceProposalDraftRequestV1,
    ) -> Result<SccpRouteGovernanceProposalDraftResponseV1> {
        validate_sccp_route_governance_draft_request(request, &self.network_id)?;
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::GOV_PROPOSE_SCCP.path(),
        );
        let body = norito::json::to_vec(request)?;
        let resp = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(GOVERNANCE_PROPOSAL_JSON_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &resp,
            StatusCode::OK,
            "Failed to draft SCCP route governance",
            " ",
        )?;
        let content_type = Self::response_content_type(&resp);
        if !Self::is_exact_json_content_type(content_type) {
            return Err(eyre!(
                "SCCP route-governance draft response has invalid content type {content_type}"
            ));
        }
        let response: SccpRouteGovernanceProposalDraftResponseV1 =
            norito::json::from_slice(resp.body())
                .wrap_err("failed to decode typed SCCP route-governance draft response")?;
        validate_sccp_route_governance_draft_response(&response, request, &self.network_id)?;
        Ok(response)
    }

    /// Draft one canonical attempt-based Parliament proposal for local signing.
    ///
    /// The response is rejected unless its derived identifiers and decoded
    /// instruction exactly match the request.
    ///
    /// # Errors
    /// Returns an error for an unsupported request version, transport or HTTP
    /// failure, malformed JSON, or any response-binding mismatch.
    pub fn post_parliament_attempt_draft(
        &self,
        request: &ParliamentAttemptDraftRequestV1,
    ) -> Result<ParliamentAttemptDraftResponseV1> {
        if request.version != PARLIAMENT_API_VERSION_V1 {
            return Err(eyre!("unsupported Parliament attempt draft version"));
        }
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::GOV_PARLIAMENT_ATTEMPT_DRAFT.path(),
        );
        let body = norito::json::to_vec(request)
            .wrap_err("failed to encode Parliament attempt draft request")?;
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(PARLIAMENT_JSON_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &response,
            StatusCode::OK,
            "Failed to draft Parliament governance attempt",
            " ",
        )?;
        let result: ParliamentAttemptDraftResponseV1 = norito::json::from_slice(response.body())
            .wrap_err("failed to decode Parliament attempt draft response")?;
        let _ = validate_parliament_attempt_draft_response(&result, request)?;
        Ok(result)
    }

    /// Draft one exact Parliament lifecycle transition for local signing.
    ///
    /// Static corpus bounds are checked before sending, and the response is
    /// rejected unless its classification, digest, and decoded instruction are
    /// all bound to the exact request.
    ///
    /// # Errors
    /// Returns an error for an invalid request, transport or HTTP failure,
    /// malformed JSON, or any response-binding mismatch.
    pub fn post_parliament_transition_draft(
        &self,
        request: &ParliamentTransitionDraftRequestV1,
    ) -> Result<ParliamentTransitionDraftResponseV1> {
        request
            .validate_static()
            .map_err(|reason| eyre!("invalid Parliament transition draft request: {reason}"))?;
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::GOV_PARLIAMENT_TRANSITION_DRAFT.path(),
        );
        let body = norito::json::to_vec(request)
            .wrap_err("failed to encode Parliament transition draft request")?;
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(PARLIAMENT_JSON_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &response,
            StatusCode::OK,
            "Failed to draft Parliament lifecycle transition",
            " ",
        )?;
        let result: ParliamentTransitionDraftResponseV1 = norito::json::from_slice(response.body())
            .wrap_err("failed to decode Parliament transition draft response")?;
        let _ = validate_parliament_transition_draft_response(&result, request)?;
        Ok(result)
    }

    /// Read one complete authenticated Parliament attempt projection.
    ///
    /// # Errors
    /// Returns an error for a zero or noncanonical identifier, transport or
    /// HTTP failure, malformed JSON, a mismatched attempt id, or oversized or
    /// noncanonical reducer payload hex.
    pub fn get_parliament_attempt(
        &self,
        governance_attempt_id: iroha_data_model::governance::types::GovernanceAttemptId,
    ) -> Result<ParliamentAttemptReadResponseV1> {
        if governance_attempt_id
            .as_bytes()
            .iter()
            .all(|byte| *byte == 0)
        {
            return Err(eyre!("Parliament governance attempt id must be non-zero"));
        }
        let path = torii_routes::runtime_governance::GOV_PARLIAMENT_ATTEMPT_READ
            .path()
            .replace("{governance_attempt_id}", &governance_attempt_id.to_hex());
        let url = join_torii_url(&self.torii_url, &path);
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::GET, url, Vec::new())?
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(PARLIAMENT_JSON_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &response,
            StatusCode::OK,
            "Failed to read Parliament governance attempt",
            " ",
        )?;
        let result: ParliamentAttemptReadResponseV1 = norito::json::from_slice(response.body())
            .wrap_err("failed to decode Parliament attempt read response")?;
        if result.version != PARLIAMENT_API_VERSION_V1
            || result.attempt.id != governance_attempt_id
            || !result.attempt.has_canonical_id()
        {
            return Err(eyre!(
                "Parliament attempt read response differs from the requested canonical id"
            ));
        }
        validate_parliament_attempt_state_frame(&result.state_payload_hex)?;
        Ok(result)
    }

    /// Read the driver plan of one Parliament attempt (`specs/sccp.md` §4.14.5 item 4).
    ///
    /// # Errors
    /// Returns an error for a zero identifier, transport or HTTP failure, malformed JSON, or a
    /// response for another attempt or with an execution height before its committed height.
    pub fn get_parliament_attempt_plan(
        &self,
        governance_attempt_id: iroha_data_model::governance::types::GovernanceAttemptId,
    ) -> Result<ParliamentAttemptPlanResponseV1> {
        if governance_attempt_id
            .as_bytes()
            .iter()
            .all(|byte| *byte == 0)
        {
            return Err(eyre!("Parliament governance attempt id must be non-zero"));
        }
        let path = torii_routes::runtime_governance::GOV_PARLIAMENT_ATTEMPT_PLAN
            .path()
            .replace("{governance_attempt_id}", &governance_attempt_id.to_hex());
        let url = join_torii_url(&self.torii_url, &path);
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::GET, url, Vec::new())?
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(PARLIAMENT_JSON_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &response,
            StatusCode::OK,
            "Failed to read Parliament attempt plan",
            " ",
        )?;
        let result: ParliamentAttemptPlanResponseV1 = norito::json::from_slice(response.body())
            .wrap_err("failed to decode Parliament attempt plan response")?;
        if result.version != PARLIAMENT_API_VERSION_V1
            || result.governance_attempt_id != governance_attempt_id
            || result.execution_height <= result.current_height
        {
            return Err(eyre!(
                "Parliament attempt plan response differs from the requested attempt"
            ));
        }
        Ok(result)
    }

    /// Relay one bounded canonical validation-fee proof page as untrusted bytes.
    ///
    /// The authenticated request uses this client's configured query account and
    /// `NetworkId`. Decoding only checks the current wire shape. This method does
    /// not authenticate finality, registry, witness, or checkpoint authority.
    /// Consumers must verify the returned bytes against independently pinned
    /// bindings and roots before displaying or using any policy projection.
    ///
    /// # Errors
    ///
    /// Rejects noncanonical/oversized requests, invalid request version or height,
    /// transport/HTTP failure, nonexact media type, and malformed or oversized proof.
    pub fn relay_validation_fee_current_policy_proof(
        &self,
        request_norito: &[u8],
    ) -> Result<Vec<u8>> {
        const MAX_RELAY_REQUEST: usize = 4096;
        if request_norito.is_empty() || request_norito.len() > MAX_RELAY_REQUEST {
            return Err(eyre!("validation-fee proof relay request exceeds bound"));
        }
        let request: ValidationFeeCurrentPolicyProofRequestV1 =
            norito::decode_canonical_with_limits(
                request_norito,
                norito::canonical_decode_limits(request_norito.len()),
            )
            .wrap_err("validation-fee proof relay request is not canonical current Norito")?;
        if request.version != VALIDATION_FEE_POLICY_PROOF_VERSION_V1
            || request.trusted_checkpoint_height == 0
        {
            return Err(eyre!(
                "invalid validation-fee proof relay request version or height"
            ));
        }
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::VALIDATION_FEE_CURRENT_POLICY_PROOF_PATH,
        );
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, request_norito.to_vec())?
                .header("Content-Type", APPLICATION_NORITO)
                .header("Accept", APPLICATION_NORITO)
                .max_response_bytes(VALIDATION_FEE_PROOF_RESPONSE_MAX_BYTES),
        )?;
        if response.status() != StatusCode::OK {
            return Err(eyre!(
                "validation-fee proof relay returned a non-success HTTP status"
            ));
        }
        if exact_single_response_header(&response, "content-type")? != APPLICATION_NORITO
            || response.headers().contains_key("x-iroha-reject-code")
            || response
                .headers()
                .keys()
                .any(|name| name.as_str().starts_with("sora-"))
        {
            return Err(eyre!(
                "validation-fee proof relay has invalid response headers"
            ));
        }
        let body = response.body();
        if body.is_empty() || body.len() > VALIDATION_FEE_PROOF_RESPONSE_MAX_BYTES {
            return Err(eyre!("validation-fee proof relay response exceeds bound"));
        }
        let proof: ValidationFeeCurrentPolicyProofV1 =
            norito::decode_canonical_with_limits(body, norito::canonical_decode_limits(body.len()))
                .wrap_err("validation-fee proof relay response is not canonical current Norito")?;
        if proof.version != VALIDATION_FEE_POLICY_PROOF_VERSION_V1
            || proof.evaluated_block_height == 0
            || proof.observed_ledger_tip_height < proof.evaluated_block_height
            || proof.more_available != (proof.evaluated_block_height < proof.observed_ledger_tip_height)
            || proof.finality_chain.is_empty()
            || proof.finality_chain.len() > iroha_torii_shared::validation_fee_api::VALIDATION_FEE_POLICY_PROOF_MAX_FINALITY_PROOFS {
            return Err(eyre!("validation-fee proof relay response has invalid current proof shape"));
        }
        // No verify_against: the relay must not substitute its own trust anchor
        // for the independently pinned checkpoint of each consuming application.
        Ok(body.clone())
    }

    /// Fetch and verify one bounded validation-fee policy proof page.
    ///
    /// The caller supplies a previously trusted checkpoint. The returned page
    /// must begin at that exact height/context and advances by at most 63
    /// blocks, authenticating the complete registry through the Commit-QC
    /// ordinary-write root.
    ///
    /// # Errors
    ///
    /// Returns an error for an invalid anchor, transport/HTTP failure,
    /// non-Norito response, malformed proof, or any finality/registry/witness
    /// verification failure.
    pub fn get_validation_fee_current_policy_proof_page(
        &self,
        trusted_checkpoint: &SumeragiFinalityCheckpoint,
    ) -> Result<(
        ValidationFeeCurrentPolicyProofV1,
        SumeragiFinalityCheckpoint,
    )> {
        if trusted_checkpoint.network_id() != self.network_id {
            return Err(eyre!("trusted checkpoint belongs to a different network"));
        }
        let request = ValidationFeeCurrentPolicyProofRequestV1 {
            version: VALIDATION_FEE_POLICY_PROOF_VERSION_V1,
            trusted_checkpoint_height: trusted_checkpoint.height(),
        };
        let body = to_bytes(&request)
            .wrap_err("failed to encode validation-fee proof request as Norito")?;
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::VALIDATION_FEE_CURRENT_POLICY_PROOF_PATH,
        );
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_NORITO)
                .header("Accept", APPLICATION_NORITO)
                .max_response_bytes(VALIDATION_FEE_PROOF_RESPONSE_MAX_BYTES),
        )?;
        if response.status() != StatusCode::OK {
            return Err(eyre!(
                "Failed to fetch validation-fee policy proof: {} {}",
                response.status(),
                std::str::from_utf8(response.body()).unwrap_or("")
            ));
        }
        let content_type = Self::response_content_type(&response);
        if !content_type.starts_with(APPLICATION_NORITO) {
            return Err(eyre!(
                "validation-fee policy proof response has invalid content type {content_type}"
            ));
        }
        let proof: ValidationFeeCurrentPolicyProofV1 = decode_from_bytes(response.body())
            .wrap_err("failed to decode validation-fee policy proof")?;
        let promoted_checkpoint = proof
            .verify_against(self.network_id, trusted_checkpoint)
            .map_err(|error| eyre!("validation-fee policy proof verification failed: {error}"))?;
        Ok((proof, promoted_checkpoint))
    }
    /// Repeatedly verify bounded validation-fee proof pages until Torii's observed tip.
    ///
    /// Applications that persist checkpoints should call the page method
    /// directly and durably store each returned native checkpoint before
    /// requesting the next page. This convenience method verifies the same
    /// sequence in memory and returns the final promoted checkpoint.
    ///
    /// # Errors
    ///
    /// Returns an error when any page fails or does not advance, or when a
    /// hostile endpoint attempts an unbounded pagination loop.
    pub fn catch_up_validation_fee_current_policy_proof(
        &self,
        trusted_checkpoint: &SumeragiFinalityCheckpoint,
    ) -> Result<ValidationFeePolicyProofCatchUp> {
        const MAX_PAGES_PER_CALL: u32 = 4_096;
        let mut checkpoint = trusted_checkpoint.clone();
        for pages_verified in 1..=MAX_PAGES_PER_CALL {
            let (page, promoted_checkpoint) =
                self.get_validation_fee_current_policy_proof_page(&checkpoint)?;
            if page.evaluated_block_height < checkpoint.height()
                || (page.more_available && page.evaluated_block_height == checkpoint.height())
            {
                return Err(eyre!("validation-fee checkpoint promotion did not advance"));
            }
            checkpoint = promoted_checkpoint;
            if !page.more_available {
                return Ok(ValidationFeePolicyProofCatchUp {
                    final_page: page,
                    pages_verified,
                    promoted_checkpoint: checkpoint,
                });
            }
        }
        Err(eyre!(
            "validation-fee checkpoint promotion exceeded {MAX_PAGES_PER_CALL} pages"
        ))
    }
    /// Read one bounded page of typed validation-fee Parliament proposals.
    ///
    /// # Errors
    ///
    /// Returns an error for an invalid cursor or limit, transport/HTTP/JSON
    /// failure, or a response whose page boundary, proposal id, operator,
    /// certificate summary, kind, or version is inconsistent.
    pub fn list_validation_fee_proposals_page(
        &self,
        cursor: Option<&str>,
        limit: u32,
    ) -> Result<ValidationFeeProposalListV1> {
        if limit == 0 || limit > VALIDATION_FEE_PROPOSAL_PAGE_MAX_LIMIT_V1 {
            return Err(eyre!(
                "validation-fee proposal page limit must be between 1 and {}",
                VALIDATION_FEE_PROPOSAL_PAGE_MAX_LIMIT_V1
            ));
        }
        let after = cursor
            .map(decode_validation_fee_proposal_cursor_v1)
            .transpose()
            .map_err(|error| eyre!("invalid validation-fee proposal cursor: {error}"))?;
        let mut url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::VALIDATION_FEE_PROPOSALS_PATH,
        );
        url.query_pairs_mut()
            .append_pair("limit", &limit.to_string());
        if let Some(cursor) = cursor {
            url.query_pairs_mut().append_pair("cursor", cursor);
        }
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::GET, url, Vec::new())?
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(VALIDATION_FEE_JSON_RESPONSE_MAX_BYTES),
        )?;
        if response.status() != StatusCode::OK {
            return Err(eyre!(
                "Failed to list validation-fee proposals: {} {}",
                response.status(),
                std::str::from_utf8(response.body()).unwrap_or("")
            ));
        }
        let result: ValidationFeeProposalListV1 = norito::json::from_slice(response.body())
            .wrap_err("failed to decode validation-fee proposal list")?;
        if result.version != VALIDATION_FEE_PROPOSAL_API_VERSION_V1 {
            return Err(eyre!(
                "validation-fee proposal list has an unsupported version"
            ));
        }
        let limit_usize = usize::try_from(limit).expect("bounded u32 page limit fits usize");
        if result.limit != limit || result.proposals.len() > limit_usize {
            return Err(eyre!(
                "validation-fee proposal page violates the requested limit"
            ));
        }
        let mut order_keys = Vec::with_capacity(result.proposals.len());
        for proposal in &result.proposals {
            let created_height = validate_validation_fee_proposal_record(proposal)?;
            order_keys.push((created_height, proposal.kind.fingerprint()));
        }
        if order_keys.windows(2).any(|pair| pair[0] > pair[1]) {
            return Err(eyre!(
                "validation-fee proposal list is not canonically ordered"
            ));
        }
        if let (Some((after_height, after_id)), Some((first_height, first_id))) =
            (after, order_keys.first().copied())
            && (first_height, first_id) <= (after_height, after_id)
        {
            return Err(eyre!(
                "validation-fee proposal page did not advance beyond its cursor"
            ));
        }
        if let Some(next_cursor) = result.next_cursor.as_deref() {
            if result.proposals.len() != limit_usize {
                return Err(eyre!(
                    "a short validation-fee proposal page cannot advertise a next cursor"
                ));
            }
            let next = decode_validation_fee_proposal_cursor_v1(next_cursor)
                .map_err(|error| eyre!("invalid validation-fee next cursor: {error}"))?;
            let Some((last_height, last_id)) = order_keys.last().copied() else {
                return Err(eyre!(
                    "empty validation-fee proposal page cannot advertise a next cursor"
                ));
            };
            if next != (last_height, last_id) {
                return Err(eyre!(
                    "validation-fee next cursor is not bound to the last returned proposal"
                ));
            }
        }
        Ok(result)
    }
    /// Read one typed validation-fee Parliament proposal.
    ///
    /// # Errors
    ///
    /// Returns an error for a malformed id, transport/HTTP/JSON failure, or a
    /// response not bound to the requested native proposal fingerprint.
    pub fn get_validation_fee_proposal(
        &self,
        proposal_id: &str,
    ) -> Result<ValidationFeeProposalDetailV1> {
        Self::require_lower_hex_32(proposal_id, "proposal_id")?;
        let path = torii_routes::runtime_governance::VALIDATION_FEE_PROPOSAL_DETAIL_PATH
            .replace("{proposal_id}", proposal_id);
        let url = join_torii_url(&self.torii_url, &path);
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::GET, url, Vec::new())?
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(VALIDATION_FEE_JSON_RESPONSE_MAX_BYTES),
        )?;
        if response.status() != StatusCode::OK {
            return Err(eyre!(
                "Failed to get validation-fee proposal: {} {}",
                response.status(),
                std::str::from_utf8(response.body()).unwrap_or("")
            ));
        }
        let result: ValidationFeeProposalDetailV1 = norito::json::from_slice(response.body())
            .wrap_err("failed to decode validation-fee proposal detail")?;
        if result.version != VALIDATION_FEE_PROPOSAL_API_VERSION_V1
            || hex::encode(result.proposal.kind.fingerprint()) != proposal_id
        {
            return Err(eyre!(
                "validation-fee proposal detail differs from the requested id or version"
            ));
        }
        validate_validation_fee_proposal_record(&result.proposal)?;
        validate_validation_fee_proposal_detail(&result)?;
        Ok(result)
    }
    /// Draft one exact native validation-fee proposal for local signing.
    ///
    /// # Errors
    ///
    /// Returns an error before HTTP for malformed payloads, and rejects any
    /// server response whose operator-bound proposal kind/id/instruction
    /// differs from the exact request.
    pub fn post_validation_fee_proposal_draft(
        &self,
        request: &ValidationFeeProposalDraftRequestV1,
    ) -> Result<ValidationFeeProposalDraftResponseV1> {
        if request.proposal_operator != self.account {
            return Err(eyre!(
                "validation-fee proposal operator must equal the client transaction authority"
            ));
        }
        let _ = canonical_validation_fee_draft_instruction(request)?;
        let url = join_torii_url(
            &self.torii_url,
            torii_routes::runtime_governance::VALIDATION_FEE_PROPOSAL_DRAFT_PATH,
        );
        let body = norito::json::to_vec(request)
            .wrap_err("failed to encode validation-fee proposal draft")?;
        let response = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(VALIDATION_FEE_JSON_RESPONSE_MAX_BYTES),
        )?;
        if response.status() != StatusCode::OK {
            return Err(eyre!(
                "Failed to draft validation-fee proposal: {} {}",
                response.status(),
                std::str::from_utf8(response.body()).unwrap_or("")
            ));
        }
        let result: ValidationFeeProposalDraftResponseV1 =
            norito::json::from_slice(response.body())
                .wrap_err("failed to decode validation-fee proposal draft response")?;
        let _ = validate_validation_fee_draft_response(&result, request)?;
        Ok(result)
    }
    /// Draft a ZK ballot instruction via `/v1/gov/ballots/zk-v1`.
