    /// GET public `/v1/node/capabilities` without canonical account authentication.
    /// Discovery must work before the transaction authority has registered an account.
    /// Returns `{ abi_version: n, data_model_version: n, signed_transaction_schema_hash_hex: "...", crypto: { ... } }`.
    /// # Errors
    /// Returns an error if the HTTP request fails, the response is non-OK, or JSON deserialization fails.
    pub fn get_node_capabilities_json(&self) -> Result<norito::json::Value> {
        let response = self.send_prepared_request(self.node_capabilities_request()?)?;
        Self::decode_node_capabilities_response(&response)
    }

    /// Refresh this context's cached node compatibility decision.
    ///
    /// Concurrent refreshes and submissions share one context-local probe. A
    /// transport, HTTP, or decoding failure is returned to those callers but is
    /// not cached; a later call probes again.
    ///
    /// # Errors
    /// Returns a typed compatibility error or [`CapabilityProbeError`].
    pub async fn refresh_capabilities(&self) -> Result<()> {
        self.ensure_compatibility(CompatibilityRequirement::Submission, true)
            .await
    }

    fn node_capabilities_request(&self) -> Result<DefaultRequest> {
        let url = join_torii_url(&self.torii_url, "v1/node/capabilities");
        let request = self
            .request_without_canonical_account_auth(HttpMethod::GET, url)
            .header(http::header::ACCEPT, APPLICATION_JSON)
            .max_response_bytes(NODE_CAPABILITIES_RESPONSE_MAX_BYTES)
            .build()?;
        Ok(request)
    }

    async fn fetch_node_capabilities(&self) -> Result<norito::json::Value> {
        let response = self.node_capabilities_request()?.send().await?;
        self.enforce_alias_policy(&response)?;
        Self::decode_node_capabilities_response(&response)
    }

    fn decode_node_capabilities_response(resp: &Response<Vec<u8>>) -> Result<norito::json::Value> {
        Self::ensure_response_status(resp, StatusCode::OK, "Failed to get node capabilities", " ")?;
        let content_type = exact_single_response_header(resp, "content-type")?;
        if !content_type.eq_ignore_ascii_case(APPLICATION_JSON)
            && !content_type.eq_ignore_ascii_case(APPLICATION_JSON_UTF8)
        {
            return Err(eyre!(
                "node capabilities response must contain canonical JSON; received `{content_type}`"
            ));
        }
        norito::json::from_slice(resp.body()).wrap_err("failed to decode node capabilities JSON")
    }
    /// GET `/v1/privacy/capabilities`.
    ///
    /// Returns the authoritative committed Exact12 capability manifest as
    /// validated canonical JSON. Static SDK catalogs are not consulted.
    ///
    /// # Errors
    ///
    /// Returns an error for a failed request, non-OK status, non-JSON media
    /// type, oversized response, unknown or malformed field, noncanonical
    /// protocol ordering, or any invalid profile/activation binding.
    pub fn get_privacy_capabilities_json(&self) -> Result<norito::json::Value> {
        let url = join_torii_url(&self.torii_url, "v1/privacy/capabilities");
        let resp = self.send_builder(
            self.account_signed_get_request(url)?
                .header("Accept", APPLICATION_JSON)
                .max_response_bytes(PRIVACY_CAPABILITIES_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &resp,
            StatusCode::OK,
            "Failed to get privacy capabilities",
            " ",
        )?;
        let content_type = Self::response_content_type(&resp);
        if !Self::is_exact_json_content_type(content_type) {
            return Err(eyre!(
                "privacy capabilities response has invalid content type {content_type}"
            ));
        }
        let manifest: PrivacyExact12CapabilityManifestV1 = norito::json::from_slice(resp.body())
            .wrap_err("failed to decode typed privacy capabilities JSON")?;
        manifest
            .validate()
            .map_err(|error| eyre!("node returned invalid privacy capabilities: {error}"))?;
        norito::json::to_value(&manifest)
            .wrap_err("failed to render validated privacy capabilities JSON")
    }
    /// GET `/v1/privacy/capabilities`.
    ///
    /// Returns the authoritative committed Exact12 capability manifest as one
    /// canonical typed Norito payload.
    ///
    /// # Errors
    ///
    /// Returns an error for a failed request, non-OK status, non-Norito media
    /// type, oversized response, noncanonical or malformed encoding, or any
    /// invalid profile/activation binding.
    pub fn get_privacy_capabilities(&self) -> Result<PrivacyExact12CapabilityManifestV1> {
        let url = join_torii_url(&self.torii_url, "v1/privacy/capabilities");
        let resp = self.send_builder(
            self.account_signed_get_request(url)?
                .header("Accept", APPLICATION_NORITO)
                .max_response_bytes(PRIVACY_CAPABILITIES_RESPONSE_MAX_BYTES),
        )?;
        Self::ensure_response_status(
            &resp,
            StatusCode::OK,
            "Failed to get privacy capabilities",
            " ",
        )?;
        let content_type = Self::response_content_type(&resp);
        if !Self::is_norito_content_type(content_type) {
            return Err(eyre!(
                "privacy capabilities response has invalid content type {content_type}"
            ));
        }
        let manifest: PrivacyExact12CapabilityManifestV1 =
            norito::decode_from_bytes(resp.body())
                .wrap_err("failed to decode privacy capabilities")?;
        if !manifest
            .canonical_bytes()
            .is_ok_and(|canonical| canonical.as_slice() == resp.body().as_slice())
        {
            return Err(eyre!(
                "privacy capabilities response is not one canonical Norito payload"
            ));
        }
        manifest
            .validate()
            .map_err(|error| eyre!("node returned invalid privacy capabilities: {error}"))?;
        Ok(manifest)
    }
