    #[test]
    fn authority_context_binding_rejects_ambiguous_or_unbound_identity_state() {
        let mut client = Client::builder(config_factory());
        client.torii_url = "ftp://example.test/".parse().expect("URL fixture");
        assert!(matches!(
            client.clone().build(),
            Err(SdkError::Context(
                AuthorityContextError::UnsupportedEndpointScheme { .. }
            ))
        ));

        client.torii_url = "https://user:secret@example.test/"
            .parse()
            .expect("URL fixture");
        {
            let actual_error = client.clone().build().expect_err("embedded credentials");
            let SdkError::Context(actual_source) = &actual_error else {
                panic!("unexpected SDK error: {actual_error:?}");
            };
            assert_eq!(
                actual_source,
                &(AuthorityContextError::EmbeddedEndpointCredentials)
            );
        };

        client.torii_url = "https://example.test/api".parse().expect("URL fixture");
        assert_eq!(
            client
                .clone()
                .build()
                .expect("a base path is a directory")
                .endpoint()
                .as_str(),
            "https://example.test/api/",
            "the builder normalizes the base path exactly as configuration files do"
        );

        client.torii_url = base_url();
        client.network_id = test_network_id();
        client.account = AccountId::new(checked_random_keypair().public_key().clone());
        {
            let actual_error = client.clone().build().expect_err("unbound account key");
            let SdkError::Context(actual_source) = &actual_error else {
                panic!("unexpected SDK error: {actual_error:?}");
            };
            assert_eq!(
                actual_source,
                &(AuthorityContextError::AccountSigningKeyMismatch)
            );
        };

        let nonmember = checked_random_keypair();
        let policy = MultisigPolicy::new(
            1,
            vec![
                MultisigMember::new(nonmember.public_key().clone(), 1)
                    .expect("valid multisig member"),
            ],
        )
        .expect("valid multisig policy");
        client.account = AccountId::new_multisig(policy);
        {
            let actual_error = client
                .clone()
                .build()
                .expect_err("nonmember account key must not bind");
            let SdkError::Context(actual_source) = &actual_error else {
                panic!("unexpected SDK error: {actual_error:?}");
            };
            assert_eq!(
                actual_source,
                &(AuthorityContextError::AccountSigningKeyNotMultisigMember)
            );
        };
    }

    #[test]
    fn concurrently_injected_client_contexts_do_not_crosstalk() {
        #[derive(Debug)]
        struct TaggedTransport {
            barrier: Arc<Barrier>,
            expected_path: &'static str,
            response_body: &'static [u8],
            sends: Arc<AtomicUsize>,
        }

        impl TaggedTransport {
            fn respond(&self, request: &crate::http::TransportRequest) -> HttpResponse<Vec<u8>> {
                self.barrier.wait();
                assert_eq!(request.url.path(), self.expected_path);
                self.sends.fetch_add(1, Ordering::Relaxed);
                HttpResponse::new(self.response_body.to_vec())
            }
        }

        impl crate::http::HttpTransport for TaggedTransport {
            fn send_blocking(
                &self,
                request: crate::http::TransportRequest,
            ) -> Result<HttpResponse<Vec<u8>>> {
                Ok(self.respond(&request))
            }

            fn send(
                &self,
                request: crate::http::TransportRequest,
            ) -> crate::http::TransportFuture<'_> {
                let response = self.respond(&request);
                Box::pin(async move { Ok(response) })
            }
        }

        let barrier = Arc::new(Barrier::new(2));
        let sends_a = Arc::new(AtomicUsize::new(0));
        let sends_b = Arc::new(AtomicUsize::new(0));
        let client_a = Client::builder(Config {
            torii_api_url: base_url(),
            ..config_factory()
        })
        .http_transport(Arc::new(TaggedTransport {
            barrier: Arc::clone(&barrier),
            expected_path: "/context-a",
            response_body: b"transport-a",
            sends: Arc::clone(&sends_a),
        }))
        .build()
        .expect("valid client configuration");
        let client_b = Client::builder(Config {
            torii_api_url: base_url(),
            ..config_factory()
        })
        .http_transport(Arc::new(TaggedTransport {
            barrier,
            expected_path: "/context-b",
            response_body: b"transport-b",
            sends: Arc::clone(&sends_b),
        }))
        .build()
        .expect("valid client configuration");

        let (body_a, body_b) = std::thread::scope(|scope| {
            let request_a = scope.spawn(|| {
                client_a
                    .default_request(
                        HttpMethod::GET,
                        join_torii_url(&client_a.torii_url, "context-a"),
                    )
                    .build()
                    .expect("context A request")
                    .send_blocking()
                    .expect("context A response")
                    .into_body()
            });
            let request_b = scope.spawn(|| {
                client_b
                    .default_request(
                        HttpMethod::GET,
                        join_torii_url(&client_b.torii_url, "context-b"),
                    )
                    .build()
                    .expect("context B request")
                    .send_blocking()
                    .expect("context B response")
                    .into_body()
            });
            (
                request_a.join().expect("context A thread"),
                request_b.join().expect("context B thread"),
            )
        });

        assert_eq!(body_a, b"transport-a");
        assert_eq!(body_b, b"transport-b");
        assert_eq!(sends_a.load(Ordering::Relaxed), 1);
        assert_eq!(sends_b.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn transaction_batch_outcomes_require_exact_order_status_and_count() {
        use iroha_data_model::transaction::receipt::TransactionBatchEntryOutcome;
        let hashes =
            [0x51, 0x52].map(|byte| HashOf::from_untyped_unchecked(Hash::prehashed([byte; 32])));
        let outcomes = vec![
            TransactionBatchEntryOutcome {
                signed_transaction_hash: hashes[0],
                status: 202,
                reject_code: None,
            },
            TransactionBatchEntryOutcome {
                signed_transaction_hash: hashes[1],
                status: 503,
                reject_code: Some("transaction_dispatch_outcome_unknown".to_owned()),
            },
        ];
        let response = |items: &Vec<TransactionBatchEntryOutcome>, count: &str| {
            HttpResponse::builder()
                .status(StatusCode::MULTI_STATUS)
                .header("x-iroha-transactions-accepted", count)
                .body(norito::json::to_vec(items).unwrap())
                .unwrap()
        };
        assert_eq!(
            transaction_batch_outcomes(&response(&outcomes, "1"), &hashes).unwrap(),
            outcomes
        );
        assert!(transaction_batch_outcomes(&response(&outcomes, "2"), &hashes).is_err());
        let mut changed = outcomes.clone();
        changed.swap(0, 1);
        assert!(transaction_batch_outcomes(&response(&changed, "1"), &hashes).is_err());
        let mut changed = outcomes.clone();
        changed[1].status = 200;
        assert!(transaction_batch_outcomes(&response(&changed, "1"), &hashes).is_err());
        let mut changed = outcomes.clone();
        changed.pop();
        assert!(transaction_batch_outcomes(&response(&changed, "1"), &hashes).is_err());
        let error = TransactionBatchAdmissionError {
            hashes: hashes.to_vec(),
            outcomes: Some(outcomes.clone()),
            cause: eyre!("partial"),
        };
        assert_eq!(error.hashes(), &hashes);
        assert_eq!(error.outcomes(), Some(outcomes.as_slice()));
    }

    #[tokio::test]
    async fn async_transaction_paths_use_the_injected_context_transport() {
        #[derive(Debug)]
        struct AsyncTransactionTransport {
            sync_sends: Arc<AtomicUsize>,
            async_paths: Arc<Mutex<Vec<String>>>,
        }

        impl crate::http::HttpTransport for AsyncTransactionTransport {
            fn send_blocking(
                &self,
                _request: crate::http::TransportRequest,
            ) -> Result<HttpResponse<Vec<u8>>> {
                self.sync_sends.fetch_add(1, Ordering::Relaxed);
                panic!("async transaction submission used the blocking transport path")
            }

            fn send(
                &self,
                request: crate::http::TransportRequest,
            ) -> crate::http::TransportFuture<'_> {
                self.async_paths
                    .lock()
                    .expect("async path log")
                    .push(request.url.path().to_owned());
                let accepted_count =
                    if request.url.path() == torii_routes::pipeline::TRANSACTIONS_BATCH.path() {
                        Some("1")
                    } else {
                        None
                    };
                Box::pin(async move {
                    let mut response = HttpResponse::builder().status(StatusCode::ACCEPTED);
                    if let Some(count) = accepted_count {
                        response = response.header("x-iroha-transactions-accepted", count);
                    }
                    response.body(Vec::new()).map_err(Into::into)
                })
            }
        }

        let sync_sends = Arc::new(AtomicUsize::new(0));
        let async_paths = Arc::new(Mutex::new(Vec::new()));
        let client = Client::builder(Config {
            torii_api_url: base_url(),
            ..config_factory()
        })
        .http_transport(Arc::new(AsyncTransactionTransport {
            sync_sends: Arc::clone(&sync_sends),
            async_paths: Arc::clone(&async_paths),
        }))
        .build()
        .expect("valid client configuration");
        mark_data_model_compatible(&client);
        let transaction = empty_transaction(&client);
        let expected_hash = transaction.hash();
        let account = client.account_client().expect("valid account context");

        assert_eq!(
            account
                .submit_transaction(&transaction)
                .await
                .expect("single async submission"),
            expected_hash
        );
        let payload = PreparedTransactionPayload::from_transaction(&transaction);
        assert_eq!(
            account
                .submit_prepared_transaction_payload_batch(&[payload])
                .await
                .expect("batch async submission"),
            vec![expected_hash]
        );
        assert_eq!(sync_sends.load(Ordering::Relaxed), 0);
        assert_eq!(
            *async_paths.lock().expect("async path log"),
            [
                torii_routes::pipeline::TRANSACTION.path(),
                torii_routes::pipeline::TRANSACTIONS_BATCH.path()
            ]
        );
    }
    #[test]
    fn owned_async_http_client_does_not_follow_signed_body_redirects() {
        let client = client_with_base_url(base_url());
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("build async HTTP test runtime");
        for (status_code, reason) in [
            (307_u16, "Temporary Redirect"),
            (308_u16, "Permanent Redirect"),
        ] {
            let redirect_listener = TcpListener::bind("127.0.0.1:0").expect("redirect listener");
            let redirect_addr = redirect_listener.local_addr().expect("redirect address");
            let target_listener = TcpListener::bind("127.0.0.1:0").expect("target listener");
            let target_addr = target_listener.local_addr().expect("target address");
            target_listener
                .set_nonblocking(true)
                .expect("nonblocking target listener");
            let redirect_server = std::thread::spawn(move || {
                let (mut stream, _) = redirect_listener.accept().expect("redirect request");
                let mut request = [0_u8; 1024];
                let request_len = stream.read(&mut request).expect("read redirect request");
                assert!(request_len > 0, "redirect request must not be empty");
                write!(
                    stream,
                    "HTTP/1.1 {status_code} {reason}\r\nLocation: http://{target_addr}/target\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"
                )
                .expect("write redirect response");
            });
            let target_server = std::thread::spawn(move || {
                let deadline = Instant::now() + Duration::from_millis(750);
                loop {
                    match target_listener.accept() {
                        Ok((mut stream, _)) => {
                            let mut request = [0_u8; 1024];
                            let request_len =
                                stream.read(&mut request).expect("read redirected request");
                            assert!(request_len > 0, "redirected request must not be empty");
                            stream
                                .write_all(
                                    b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                                )
                                .expect("write target response");
                            return true;
                        }
                        Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                            if Instant::now() >= deadline {
                                return false;
                            }
                            std::thread::sleep(Duration::from_millis(10));
                        }
                        Err(error) => panic!("target listener failed: {error}"),
                    }
                }
            });
            let response = runtime
                .block_on(async {
                    client
                        .default_request(
                            HttpMethod::POST,
                            Url::parse(&format!("http://{redirect_addr}/transaction"))
                                .expect("redirect URL"),
                        )
                        .body(vec![0x01, 0x02, 0x03])
                        .build()
                        .expect("build redirect request")
                        .send()
                        .await
                })
                .expect("redirect response");
            redirect_server.join().expect("redirect server");
            let followed = target_server.join().expect("target server");
            assert_eq!(response.status().as_u16(), status_code);
            assert!(!followed, "one-shot signed body must not be redirected");
        }
    }
    #[test]
    fn owned_async_http_client_does_not_retry_signed_body_after_server_response() {
        let client = client_with_base_url(base_url());
        let listener = TcpListener::bind("127.0.0.1:0").expect("test listener");
        let address = listener.local_addr().expect("test address");
        let server = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("first request");
            let mut request = [0_u8; 1024];
            let request_len = stream.read(&mut request).expect("read first request");
            assert!(request_len > 0, "first request must not be empty");
            stream
                .write_all(
                    b"HTTP/1.1 503 Service Unavailable\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                )
                .expect("write first response");
            drop(stream);
            listener
                .set_nonblocking(true)
                .expect("nonblocking retry listener");
            let deadline = Instant::now() + Duration::from_millis(750);
            loop {
                match listener.accept() {
                    Ok((_stream, _)) => return true,
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        if Instant::now() >= deadline {
                            return false;
                        }
                        std::thread::sleep(Duration::from_millis(10));
                    }
                    Err(error) => panic!("retry listener failed: {error}"),
                }
            }
        });
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("build async HTTP test runtime");
        let response = runtime
            .block_on(async {
                client
                    .default_request(
                        HttpMethod::POST,
                        Url::parse(&format!("http://{address}/transaction")).expect("test URL"),
                    )
                    .body(vec![0x01, 0x02, 0x03])
                    .build()
                    .expect("build signed request")
                    .send()
                    .await
            })
            .expect("server response");
        assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert!(
            !server.join().expect("test server"),
            "signed body was retried"
        );
    }
