    struct FailingClientRng;
    #[derive(Debug)]
    struct FailingClientRngError;
    impl std::fmt::Display for FailingClientRngError {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter.write_str("failing client RNG")
        }
    }
    impl rand::rand_core::TryRngCore for FailingClientRng {
        type Error = FailingClientRngError;
        fn try_next_u32(&mut self) -> std::result::Result<u32, Self::Error> {
            Err(FailingClientRngError)
        }
        fn try_next_u64(&mut self) -> std::result::Result<u64, Self::Error> {
            Err(FailingClientRngError)
        }
        fn try_fill_bytes(&mut self, _dst: &mut [u8]) -> std::result::Result<(), Self::Error> {
            Err(FailingClientRngError)
        }
    }
    impl rand::rand_core::TryCryptoRng for FailingClientRng {}
    pub(super) fn assert_canonical_account_signed_request(
        client: &Client,
        snapshot: &RequestSnapshot,
    ) {
        let headers: HashMap<_, _> = snapshot.headers.iter().cloned().collect();
        for header in [
            HEADER_ACCOUNT,
            HEADER_SIGNATURE,
            HEADER_TIMESTAMP_MS,
            HEADER_NONCE,
        ] {
            assert_eq!(
                snapshot
                    .headers
                    .iter()
                    .filter(|(name, _)| name == header)
                    .count(),
                1,
                "canonical authentication header {header} must be sent exactly once",
            );
        }
        assert_eq!(
            headers.get(HEADER_ACCOUNT),
            Some(
                &client
                    .account
                    .to_canonical_hex()
                    .expect("fixture account has canonical hexadecimal form"),
            ),
            "request signer must be the configured client account",
        );
        let account_header = headers.get(HEADER_ACCOUNT).expect("account header");
        assert!(account_header.is_ascii());
        assert!(account_header.starts_with("0x"));
        assert!(
            account_header[2..]
                .bytes()
                .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)),
            "account header must be canonical lowercase ASCII hexadecimal",
        );
        let timestamp_ms = headers
            .get(HEADER_TIMESTAMP_MS)
            .expect("timestamp header")
            .parse::<u64>()
            .expect("timestamp header should parse");
        let nonce = headers.get(HEADER_NONCE).expect("nonce header");
        assert!(!nonce.is_empty(), "nonce must not be empty");
        let signature_bytes = base64::engine::general_purpose::STANDARD
            .decode(
                headers
                    .get(HEADER_SIGNATURE)
                    .expect("signature header")
                    .as_bytes(),
            )
            .expect("signature header should decode");
        let signature = Signature::try_from_bytes(&signature_bytes)
            .expect("account signature header must pass checked admission");
        let signed_message = Client::exact_network_request_message(
            &client.network_id,
            &snapshot.method,
            &snapshot.url,
            &snapshot.body,
            timestamp_ms,
            nonce,
        )
        .expect("canonical signed message must be constructible");
        signature
            .verify(client.key_pair.public_key(), &signed_message)
            .expect("signature must cover the exact method, path, query, and body");
        assert!(
            !headers.contains_key(HEADER_WITNESS),
            "single-signature request must not retain a configured witness header",
        );
    }
    pub(super) fn assert_canonical_account_signed_json_request(
        client: &Client,
        snapshot: &RequestSnapshot,
    ) {
        assert_canonical_account_signed_request(client, snapshot);
        let headers: HashMap<_, _> = snapshot.headers.iter().cloned().collect();
        assert_eq!(
            headers.get("content-type"),
            Some(&APPLICATION_JSON.to_owned()),
        );
    }
    fn assert_unsigned_json_request(snapshot: &RequestSnapshot) {
        let headers: HashMap<_, _> = snapshot.headers.iter().cloned().collect();
        for header in [
            HEADER_ACCOUNT,
            HEADER_SIGNATURE,
            HEADER_TIMESTAMP_MS,
            HEADER_NONCE,
            HEADER_WITNESS,
        ] {
            assert!(
                !headers.contains_key(header),
                "unsigned request must not send canonical authentication header {header}",
            );
        }
        assert_eq!(
            headers.get("content-type"),
            Some(&APPLICATION_JSON.to_owned()),
        );
    }
    #[test]
    fn raw_fee_proof_relay_rejects_noncanonical_requests_before_http() {
        let client = client_with_base_url(base_url());
        let valid = to_bytes(&ValidationFeeCurrentPolicyProofRequestV1 {
            version: VALIDATION_FEE_POLICY_PROOF_VERSION_V1,
            trusted_checkpoint_height: 1,
        })
        .expect("request");
        let mut trailing = valid.clone();
        trailing.push(0);
        let invalid = vec![
            Vec::new(),
            vec![0; 4097],
            trailing,
            to_bytes(&ValidationFeeCurrentPolicyProofRequestV1 {
                version: 2,
                trusted_checkpoint_height: 1,
            })
            .unwrap(),
            to_bytes(&ValidationFeeCurrentPolicyProofRequestV1 {
                version: 1,
                trusted_checkpoint_height: 0,
            })
            .unwrap(),
        ];
        with_mock_http(
            |_| panic!("invalid proof relay request reached HTTP"),
            |transport| {
                let client = client.with_test_http_transport(transport);
                for request in invalid {
                    assert!(
                        client
                            .relay_validation_fee_current_policy_proof(&request)
                            .is_err()
                    );
                }
            },
        );
    }

    #[test]
    fn raw_fee_proof_relay_signs_exact_bounded_request_and_rejects_response_shortcuts() {
        let mut client = client_with_base_url(base_url());
        client.headers.insert("X-Dataspace-Id".into(), "is2".into());
        let request = to_bytes(&ValidationFeeCurrentPolicyProofRequestV1 {
            version: VALIDATION_FEE_POLICY_PROOF_VERSION_V1,
            trusted_checkpoint_height: 3,
        })
        .unwrap();
        for response in [
            mk_response(
                StatusCode::OK,
                br#"{"ready":true,"verified":true}"#.to_vec(),
                Some(APPLICATION_JSON),
            ),
            mk_response(StatusCode::OK, vec![0], Some(APPLICATION_NORITO)),
            mk_response(
                StatusCode::OK,
                vec![0],
                Some("application/x-norito; charset=binary"),
            ),
            mk_response(StatusCode::FOUND, vec![], Some(APPLICATION_NORITO)),
            mk_response(
                StatusCode::OK,
                vec![0; VALIDATION_FEE_PROOF_RESPONSE_MAX_BYTES + 1],
                Some(APPLICATION_NORITO),
            ),
        ] {
            let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
            with_mock_http(respond_with(&store, response), |transport| {
                assert!(
                    client
                        .clone()
                        .with_test_http_transport(transport)
                        .relay_validation_fee_current_policy_proof(&request)
                        .is_err()
                );
            });
            let snapshots = store.lock().unwrap();
            assert_eq!(snapshots.len(), 1);
            let snapshot = &snapshots[0];
            assert_eq!(snapshot.method, HttpMethod::POST);
            assert_eq!(
                snapshot.url.path(),
                "/v1/validation-fee/policy/current/proof"
            );
            assert_eq!(snapshot.body, request);
            assert_eq!(
                snapshot.max_response_bytes,
                VALIDATION_FEE_PROOF_RESPONSE_MAX_BYTES
            );
            assert_canonical_account_signed_request(&client, snapshot);
            assert!(
                snapshot
                    .headers
                    .iter()
                    .any(|(name, value)| name.eq_ignore_ascii_case("x-dataspace-id")
                        && value == "is2")
            );
        }
    }

    fn client_with_static_canonical_auth_headers() -> Client {
        let mut client = client_with_base_url(base_url());
        for header in [
            HEADER_ACCOUNT,
            HEADER_SIGNATURE,
            HEADER_TIMESTAMP_MS,
            HEADER_NONCE,
            HEADER_WITNESS,
        ] {
            client
                .headers
                .insert(header.to_owned(), "untrusted-static-value".to_owned());
        }
        client
    }
