    #[test]
    fn blocks_ws_flow_uses_framed_norito() {
        use crate::{
            crypto::{PrivateKey, PublicKey},
            data_model::{
                block::{
                    SignedBlock, builder::BlockBuilder as DataModelBlockBuilder,
                    stream::BlockMessage, stream::BlockSubscriptionRequest,
                },
                prelude::{AccountId, TransactionBuilder},
            },
        };
        use std::num::NonZeroU64;
        let height = NonZeroU64::new(1).expect("height");
        let init = blocks_api::flow::Init::new(
            height,
            HashMap::new(),
            "http://127.0.0.1:8080".parse().expect("valid url"),
        )
        .expect("init blocks handler");
        let init_data = <blocks_api::flow::Init as crate::http::ws::conn_flow::Init<
            crate::http_default::DefaultWebSocketRequestBuilder,
        >>::init(init)
        .expect("encode stream subscription");
        let decoded: BlockSubscriptionRequest = norito::decode_from_bytes(&init_data.first_message)
            .expect("decode block subscription request");
        assert_eq!(decoded.0, height);
        let public_key: PublicKey =
            "ed0120CE7FA46C9DCE7EA4B125E2E36BDB63EA33073E7590AC92816AE1E861B7048B03"
                .parse()
                .expect("public key");
        let private_key: PrivateKey =
            "802620CCF31D85E3B32A4BEA59987CE0C78E3B8E2DB93881468AB2435FE45D5C9DCD53"
                .parse()
                .expect("private key");
        let authority = AccountId::new(public_key.clone());
        let tx = TransactionBuilder::new_genesis(
            authority,
            iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
        )
        .try_sign(&private_key)
        .expect("block stream fixture transaction should sign");
        let proposal = SignedBlock::genesis(vec![tx.clone()], &private_key, None, None);
        assert!(proposal.is_resultless_proposal());
        let mut builder = DataModelBlockBuilder::new(proposal.header());
        builder.set_da_proof_policies(proposal.da_proof_policies().cloned());
        builder.push_transaction(tx);
        let mut block = builder
            .try_build_with_signature(0, &private_key)
            .expect("sign canonical result-bearing block-stream fixture");
        let proposal_header = block.header();
        let proposal_hash = block.hash();
        attach_client_fixture_outputs(
            &mut block,
            vec![client_fixture_network_output(
                0,
                Ok(iroha_data_model::transaction::DataTriggerSequence::default()).into(),
            )],
            1,
        );
        block
            .validate_proposal_commitments()
            .expect("canonical proposal commitments");
        block
            .validate_output_merkle_cache()
            .expect("canonical typed output cache");
        assert_eq!(block.committed_fragment_count(), Some(1));
        assert_eq!(block.header(), proposal_header);
        assert_eq!(block.hash(), proposal_hash);
        assert_eq!(
            block.output_merkle_commitment().unwrap().leaf_count().get(),
            1
        );
        let mut final_signatures = block.signatures();
        let final_signature = final_signatures
            .next()
            .expect("result-bearing block-stream signature");
        assert_eq!(final_signature.index(), 0);
        assert!(final_signatures.next().is_none());
        final_signature
            .signature()
            .verify_hash(&public_key, block.hash())
            .expect("verify result-bearing block-stream signature");
        let bytes = norito::to_bytes(&BlockMessage(block.clone())).expect("encode block message");
        let decoded_block = blocks_api::flow::Events
            .message(bytes)
            .expect("decode block message");
        assert_eq!(decoded_block, block);
    }
