    #[test]
    fn submit_transaction_reprobes_after_failed_capabilities_probe() {
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let capability_attempts = Arc::new(Mutex::new(0_u8));
        let responder = {
            let store = Arc::clone(&store);
            let capability_attempts = Arc::clone(&capability_attempts);
            let compatible_capabilities = compatible_capabilities_body();
            move |snapshot: RequestSnapshot| {
                let path = snapshot.url.path().to_owned();
                store.lock().expect("snapshot lock").push(snapshot);
                if path == "/v1/node/capabilities" {
                    let mut attempts = capability_attempts.lock().expect("attempt lock");
                    *attempts += 1;
                    if *attempts == 1 {
                        Ok(json_response(
                            StatusCode::SERVICE_UNAVAILABLE,
                            "temporarily unavailable",
                        ))
                    } else {
                        Ok(json_response(StatusCode::OK, &compatible_capabilities))
                    }
                } else {
                    Ok(empty_response(StatusCode::OK))
                }
            }
        };
        with_mock_http(responder, |mock_transport| {
            let client =
                client_with_base_url(base_url()).with_test_http_transport(mock_transport.clone());
            let transaction = empty_transaction(&client);
            let _ = client
                .submit_transaction_for_test(&transaction)
                .expect_err("first capability probe must fail closed");
            assert!(matches!(
                &*client
                    .data_model_compatibility
                    .lock()
                    .expect("data model compatibility lock"),
                DataModelCompatibility::Unchecked
            ));
            client
                .submit_transaction_for_test(&transaction)
                .expect("recovered capability probe should permit submission");
        });
        let snapshots = store.lock().expect("snapshot lock");
        assert_eq!(snapshots.len(), 3);
        assert_eq!(snapshots[0].url.path(), "/v1/node/capabilities");
        assert_eq!(snapshots[1].url.path(), "/v1/node/capabilities");
        assert_eq!(
            snapshots[2].url.path(),
            torii_routes::pipeline::TRANSACTION.path()
        );
    }
    #[test]
    fn blocking_facade_returns_submit_rejection_without_waiting_for_timeout() {
        use iroha_data_model::query::{
            QueryOutput, QueryOutputBatchBox, QueryOutputBatchBoxTuple, QueryResponse,
        };
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let capabilities_body = compatible_capabilities_body();
        let responder = {
            let store = Arc::clone(&store);
            move |snapshot: RequestSnapshot| {
                let path = snapshot.url.path().to_string();
                store.lock().expect("snapshot lock").push(snapshot);
                let response = match path.as_str() {
                    "/v1/node/capabilities" => json_response(StatusCode::OK, &capabilities_body),
                    p if p == torii_routes::pipeline::TRANSACTION.path() => json_response(
                        StatusCode::BAD_REQUEST,
                        r#"{"code":"transaction_rejected","message":"failed to accept transaction: missing gas limit in fee payment intent"}"#,
                    ),
                    p if p == torii_routes::pipeline::QUERY.path() => {
                        let response = QueryResponse::Iterable(QueryOutput {
                            batch: QueryOutputBatchBoxTuple::from_batch(
                                QueryOutputBatchBox::CommittedTransaction(Vec::new()),
                            ),
                            remaining_items: Some(0),
                            has_more: false,
                            continue_cursor: None,
                        });
                        HttpResponse::builder()
                            .status(StatusCode::OK)
                            .header("content-type", APPLICATION_NORITO)
                            .body(
                                norito::to_bytes(&response)
                                    .expect("encode norito committed query response"),
                            )
                            .expect("response build")
                    }
                    "/v1/pipeline/transactions/status" => HttpResponse::builder()
                        .status(StatusCode::NO_CONTENT)
                        .body(Vec::new())
                        .expect("response build"),
                    other => panic!("unexpected request path: {other}"),
                };
                Ok(response)
            }
        };
        with_mock_http(responder, |mock_transport| {
            let mut client =
                client_with_base_url(Url::parse("http://127.0.0.1:1/").expect("valid URL"))
                    .with_test_http_transport(mock_transport.clone());
            client.transaction_status_timeout = Duration::from_secs(2);
            let tx = build_transaction(
                &client,
                Vec::<InstructionBox>::new(),
                iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
                Metadata::default(),
            );
            let client = crate::blocking::Client::from_client(client)
                .expect("blocking client runtime should initialize");
            let started = Instant::now();
            let err = client
                .submit_transaction_and_wait(&tx)
                .expect_err("transaction submission should fail immediately");
            let elapsed = started.elapsed();
            assert!(
                elapsed < Duration::from_secs(1),
                "submit rejection should not wait for the 2s status timeout; elapsed={elapsed:?}"
            );
            assert!(
                err.to_string()
                    .contains("missing gas limit in fee payment intent")
            );
        });
    }
    #[test]
    fn blocking_facade_applies_configured_torii_request_timeout() {
        let snapshots: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let responder = {
            let snapshots = Arc::clone(&snapshots);
            move |snapshot: RequestSnapshot| {
                let path = snapshot.url.path().to_owned();
                snapshots.lock().expect("snapshot lock").push(snapshot);
                match path.as_str() {
                    p if p == torii_routes::pipeline::TRANSACTION.path() => Ok(json_response(
                        StatusCode::BAD_REQUEST,
                        r#"{"code":"transaction_rejected","message":"timeout snapshot rejection"}"#,
                    )),
                    "/v1/pipeline/transactions/status" => {
                        Ok(empty_response(StatusCode::NO_CONTENT))
                    }
                    other => panic!("unexpected request path: {other}"),
                }
            }
        };
        let configured_timeout = Duration::from_millis(1_234);
        with_mock_http(responder, |mock_transport| {
            let mut client =
                client_with_base_url(Url::parse("http://127.0.0.1:1/").expect("valid URL"))
                    .with_test_http_transport(mock_transport.clone());
            mark_data_model_compatible(&client);

            client.torii_request_timeout = configured_timeout;
            client.transaction_status_timeout = Duration::from_millis(50);
            let transaction = empty_transaction(&client);
            let client = crate::blocking::Client::from_client(client)
                .expect("blocking client runtime should initialize");
            let _ = client
                .submit_transaction_and_wait(&transaction)
                .expect_err("the mock rejection must terminate blocking submission");
        });

        let snapshots = snapshots.lock().expect("snapshot lock");
        let submission = snapshots
            .iter()
            .find(|snapshot| snapshot.url.path() == torii_routes::pipeline::TRANSACTION.path())
            .expect("blocking submission must issue one transaction POST");
        assert_eq!(submission.timeout, Some(configured_timeout));
    }
    #[test]
    fn blocking_confirmation_does_not_poll_before_submit_disposition() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

        let mut client =
            client_with_base_url(Url::parse("http://127.0.0.1:1/").expect("valid URL"));

        client.transaction_status_timeout = Duration::from_millis(25);
        client.torii_request_timeout = Duration::from_secs(1);
        let transaction = empty_transaction(&client);
        let hash = transaction.hash();
        let status = PipelineTransactionStatusResponse::new(
            hash.to_string(),
            iroha_torii_shared::PipelineTransactionStatus {
                kind: "Applied".to_owned(),
                block_height: Some(1),
            },
            "global".to_owned(),
            "state".to_owned(),
        );
        let status_body = norito::json::to_string(&status).expect("encode global status");
        let post_completed = Arc::new(AtomicBool::new(false));
        let status_checks = Arc::new(AtomicUsize::new(0));
        let premature_status_checks = Arc::new(AtomicUsize::new(0));
        let responder = {
            let post_completed = Arc::clone(&post_completed);
            let status_checks = Arc::clone(&status_checks);
            let premature_status_checks = Arc::clone(&premature_status_checks);
            move |snapshot: RequestSnapshot| match snapshot.url.path() {
                path if path == torii_routes::pipeline::TRANSACTION.path() => {
                    std::thread::sleep(Duration::from_millis(75));
                    post_completed.store(true, Ordering::SeqCst);
                    Ok(empty_response(StatusCode::ACCEPTED))
                }
                "/v1/pipeline/transactions/status" => {
                    status_checks.fetch_add(1, Ordering::SeqCst);
                    if !post_completed.load(Ordering::SeqCst) {
                        premature_status_checks.fetch_add(1, Ordering::SeqCst);
                    }
                    Ok(json_response(StatusCode::OK, &status_body))
                }
                other => panic!("unexpected request path: {other}"),
            }
        };

        let resolved = with_mock_http(responder, |mock_transport| {
            let client = client
                .clone()
                .with_test_http_transport(mock_transport.clone());
            mark_data_model_compatible(&client);
            crate::blocking::Client::from_client(client)
                .expect("blocking client runtime should initialize")
                .submit_transaction_and_wait(&transaction)
        })
        .expect("state-resolved Applied must finish blocking confirmation");
        assert_eq!(resolved, hash);
        assert!(
            status_checks.load(Ordering::SeqCst) >= 1,
            "the post-admission timeout fallback must query global status"
        );
        assert_eq!(
            premature_status_checks.load(Ordering::SeqCst),
            0,
            "global status must remain gated until the transaction POST reports its disposition"
        );
    }
