    #[tokio::test]
    async fn async_nonblocking_native_ambiguities_are_structured_and_never_retried() {
        for scenario in ["exact", "claimed-invalid", "truncated"] {
            let mut client = client_with_base_url(base_url());
            let transaction = empty_native_transaction(&client);
            let identity = TransactionDispatchOutcomeUnknownIdentity::for_transaction(&transaction);
            let response = match scenario {
                "exact" => raw_transaction_dispatch_outcome_unknown_response(
                    &identity,
                    &identity.signed_transaction_hash.to_string(),
                ),
                "claimed-invalid" => raw_transaction_dispatch_outcome_unknown_response(
                    &identity,
                    "ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff",
                ),
                "truncated" => {
                    b"HTTP/1.1 503 Service Unavailable\r\nContent-Type: application/x-norito\r\nContent-Length: 64\r\nConnection: close\r\n\r\ntruncated"
                        .to_vec()
                }
                _ => unreachable!(),
            };
            let (url, server) = serve_one_raw_transaction_response(response);
            client.torii_url = url;
            client.torii_request_timeout = Duration::from_secs(2);
            mark_data_model_compatible(&client);
            let account = client.account_client().expect("valid account context");

            let error = account
                .submit_transaction(&transaction)
                .await
                .expect_err("transaction ambiguity must not be reported as definite admission");
            let ambiguity = error
                .downcast_ref::<TransactionDispatchOutcomeUnknownError>()
                .expect("async transaction ambiguity must use the public structured error");
            assert_eq!(ambiguity.entrypoint_hash(), &identity.entrypoint_hash);
            assert_eq!(
                ambiguity.signed_transaction_hash(),
                &identity.signed_transaction_hash
            );
            if scenario == "claimed-invalid" {
                assert!(format!("{error:#}").contains("invalid evidence"));
            }
            if scenario == "truncated" {
                assert!(
                    format!("{error:#}").contains("Failed to read bounded async response bytes")
                );
            }
            assert!(
                !server.join().expect("async transaction response server"),
                "async {scenario} ambiguity must not auto-resubmit"
            );
        }
    }
    #[test]
    fn native_duplicate_wire_headers_remain_ambiguous() {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("test runtime");
        let cases = [
            (
                "content-type",
                "Content-Type",
                APPLICATION_NORITO.to_owned(),
                "content-type header is missing or duplicated",
            ),
            (
                "reject-code",
                "x-iroha-reject-code",
                TRANSACTION_DISPATCH_OUTCOME_UNKNOWN_REJECT_CODE.to_owned(),
                "reject-code header is missing, duplicated, or invalid",
            ),
            (
                "entrypoint identity",
                TRANSACTION_ENTRYPOINT_HASH_HEADER,
                String::new(),
                "entrypoint header is missing, duplicated, or invalid",
            ),
            (
                "signed-transaction identity",
                SIGNED_TRANSACTION_HASH_HEADER,
                String::new(),
                "signed-transaction header is missing, duplicated, or invalid",
            ),
        ];
        for asynchronous in [false, true] {
            for (scenario, header_name, mut header_value, expected_diagnostic) in cases.clone() {
                let mut client = client_with_base_url(base_url());
                let transaction = empty_native_transaction(&client);
                let identity =
                    TransactionDispatchOutcomeUnknownIdentity::for_transaction(&transaction);
                if header_value.is_empty() {
                    header_value = if header_name == TRANSACTION_ENTRYPOINT_HASH_HEADER {
                        identity.entrypoint_hash.to_string()
                    } else {
                        identity.signed_transaction_hash.to_string()
                    };
                }
                let response =
                    raw_transaction_dispatch_outcome_unknown_response_with_additional_headers(
                        &identity,
                        &identity.signed_transaction_hash.to_string(),
                        &[(header_name, header_value)],
                    );
                let (url, server) = serve_one_raw_transaction_response(response);
                client.torii_url = url;
                client.torii_request_timeout = Duration::from_secs(2);
                mark_data_model_compatible(&client);

                let (error, retried) = {
                    let error = if asynchronous {
                        let account = client.account_client().expect("valid account context");
                        runtime.block_on(account.submit_transaction(&transaction))
                    } else {
                        client.submit_transaction_for_test(&transaction)
                    }
                    .expect_err("duplicate transaction evidence cannot be exact");
                    let retried = server.join().expect("raw transaction response server");
                    (error, retried)
                };
                let ambiguity = error
                    .downcast_ref::<TransactionDispatchOutcomeUnknownError>()
                    .expect("duplicate transaction evidence must remain a structured ambiguity");
                assert_eq!(ambiguity.entrypoint_hash(), &identity.entrypoint_hash);
                assert_eq!(
                    ambiguity.signed_transaction_hash(),
                    &identity.signed_transaction_hash
                );
                let report = format!("{error:#}");
                assert!(
                    report.contains("invalid evidence") && report.contains(expected_diagnostic),
                    "{scenario} duplicate was lost before singleton validation: {report}"
                );
                assert!(
                    !retried,
                    "{scenario} ambiguity must not auto-resubmit (async={asynchronous})"
                );
            }
        }
    }
    #[test]
    fn blocking_native_transport_ambiguity_resolves_only_from_global_state() {
        let mut client = client_with_base_url(
            Url::parse("http://127.0.0.1:1/").expect("unreachable loopback URL"),
        );

        client.transaction_status_timeout = Duration::from_secs(1);
        let transaction = empty_native_transaction(&client);
        let hash = transaction.hash();
        let status = PipelineTransactionStatusResponse::new(
            hash.to_string(),
            iroha_torii_shared::PipelineTransactionStatus {
                kind: "Applied".to_owned(),
                block_height: Some(7),
            },
            "global".to_owned(),
            "state".to_owned(),
        );
        let status_body = norito::json::to_string(&status).expect("encode global status");
        let snapshots: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let responder = {
            let snapshots = Arc::clone(&snapshots);
            move |snapshot: RequestSnapshot| {
                let path = snapshot.url.path().to_owned();
                snapshots.lock().expect("snapshot lock").push(snapshot);
                if path == torii_routes::pipeline::TRANSACTION.path() {
                    Err(eyre!("connection reset after dispatch"))
                } else if path == "/v1/pipeline/transactions/status" {
                    Ok(json_response(StatusCode::OK, &status_body))
                } else {
                    panic!("unexpected request path: {path}");
                }
            }
        };
        let resolved = with_mock_http(responder, |mock_transport| {
            let client = client
                .clone()
                .with_test_http_transport(mock_transport.clone());
            mark_data_model_compatible(&client);
            crate::blocking::Client::from_client(client)
                .expect("blocking client runtime should initialize")
                .submit_transaction_and_wait(&transaction)
        })
        .expect("state-resolved global Applied must resolve transport ambiguity");
        assert_eq!(resolved, hash);
        let snapshots = snapshots.lock().expect("snapshot lock");
        assert_eq!(
            snapshots
                .iter()
                .filter(|snapshot| snapshot.url.path()
                    == torii_routes::pipeline::TRANSACTION.path())
                .count(),
            1,
            "blocking reconciliation must never auto-resubmit"
        );
        assert!(snapshots.iter().any(|snapshot| {
            snapshot.url.path() == "/v1/pipeline/transactions/status"
                && snapshot
                    .url
                    .query()
                    .is_some_and(|query| query.contains("scope=global"))
        }));
    }
