    fn capture_sorafs_endpoint(
        status: StatusCode,
        response_body: &str,
        send: impl FnOnce(&Client) -> Result<Response<Vec<u8>>>,
    ) -> (Client, RequestSnapshot) {
        let client = client_with_base_url(base_url());
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        with_mock_http(
            respond_with(&store, json_response(status, response_body)),
            |mock_transport| {
                let injected = client.clone().with_test_http_transport(mock_transport);
                send(&injected)
            },
        )
        .expect("SoraFS endpoint request");
        let snapshot = store
            .lock()
            .expect("snapshot store")
            .first()
            .cloned()
            .expect("SoraFS request snapshot");
        (client, snapshot)
    }

    fn assert_signed_json_snapshot(
        snapshot: &RequestSnapshot,
        path: &str,
        require_json_headers: bool,
    ) {
        assert_eq!(snapshot.method, HttpMethod::POST);
        assert_eq!(snapshot.url.path(), path);
        if require_json_headers {
            assert_signed_json_headers(snapshot);
        } else {
            assert_signed_headers(snapshot);
        }
    }

    fn assert_signed_json_endpoint(
        status: StatusCode,
        path: &str,
        require_json_headers: bool,
        expected_body: &[u8],
        send: impl FnOnce(&Client) -> Result<Response<Vec<u8>>>,
    ) -> RequestSnapshot {
        let (_, snapshot) = capture_sorafs_endpoint(status, "{}", send);
        assert_signed_json_snapshot(&snapshot, path, require_json_headers);
        assert_eq!(snapshot.body, expected_body);
        snapshot
    }

    fn assert_error_contains<T, E: fmt::Display>(result: Result<T, E>, expected: &str) {
        let Err(error) = result else {
            panic!("request unexpectedly succeeded")
        };
        assert!(error.to_string().contains(expected), "{error}");
    }

    #[test]
    fn sorafs_moderation_model_registry_uploads_send_signed_requests() {
        let client = client_with_base_url(base_url());
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let response = json_response(StatusCode::ACCEPTED, "{}");
        let repro_manifest: &[u8] = b"canonical repro manifest bytes";
        let corpus_manifest: &[u8] = b"canonical corpus manifest bytes";
        with_mock_http(respond_with(&store, response), |mock_transport| {
            let client = client
                .clone()
                .with_test_http_transport(mock_transport.clone());

            client
                .post_sorafs_moderation_model_registry_repro_manifest(repro_manifest)
                .expect("moderation model registry repro request");
            client
                .post_sorafs_moderation_model_registry_corpus(corpus_manifest)
                .expect("moderation model registry corpus request");
        });
        let snapshots = store.lock().expect("snapshot store");
        let expected = [
            (
                "/v1/sorafs/moderation/model-registry/repro-manifests",
                repro_manifest,
                true,
            ),
            (
                "/v1/sorafs/moderation/model-registry/corpora",
                corpus_manifest,
                false,
            ),
        ];
        assert_eq!(snapshots.len(), expected.len());
        for (snapshot, (path, manifest, json_headers)) in snapshots.iter().zip(expected) {
            assert_eq!(snapshot.method, HttpMethod::POST);
            assert_eq!(snapshot.url.path(), path);
            if json_headers {
                assert_signed_json_headers(snapshot);
            } else {
                assert_signed_headers(snapshot);
            }
            let body: JsonValue =
                norito::json::from_slice(&snapshot.body).expect("decode request body");
            let expected_b64 = base64::engine::general_purpose::STANDARD.encode(manifest);
            assert_eq!(
                body.get("manifest_b64").and_then(JsonValue::as_str),
                Some(expected_b64.as_str())
            );
        }
    }
